/* ============================================================
   Texts in the learner's language (fr) for data/core/grammar-reference.js
   Keys map to the ids of the neutral layer; arrays join by index, so
   their length must match core. Checked by scripts/parity.mjs.

   The contrastive notes are written against French, not translated
   from another language: the point of comparison changes with the
   reader's language. Cells in the learned language (German) carry the
   historical class 'it' in the tables.
   ============================================================ */
LINGUAI.addStrings("fr", {
  "refsec:titles": [
    "Noms et articles",
    "Adjectif et adverbe",
    "Pronoms",
    "Le verbe",
    "Modes et passif",
    "Prépositions",
    "La phrase",
    "Prononciation et registre"
  ],
  "ref:g-genus": {
    title: "Le genre du nom",
    sub: "der, die, das ; -ung, -heit, -chen…",
    body: "<p>L'allemand a <b>trois genres</b> : masculin (<em>der</em>), féminin (<em>die</em>) et neutre (<em>das</em>). Le français n'en a que deux, et le genre allemand ne suit pas toujours le vôtre, il le contredit même souvent (parfois il coïncide : <em>la lampe, die Lampe</em>) : <em>le soleil</em> mais <em>die Sonne</em> (féminin), <em>la lune</em> mais <em>der Mond</em> (masculin), <em>la table</em> mais <em>der Tisch</em> (masculin). Ne traduisez donc jamais le genre : apprenez chaque nom <b>avec son article</b>, comme un seul bloc : <em>der Tisch, die Lampe, das Buch</em>.</p><h4>Indices utiles</h4><ul><li><b>die</b> : les noms en <em>-ung, -heit, -keit, -schaft, -ion, -tät</em> (<em>die Zeitung, die Freiheit, die Möglichkeit, die Freundschaft, die Nation, die Universität</em>) et les féminins de personnes en <em>-in</em> (<em>die Lehrerin</em>).</li><li><b>das</b> : les diminutifs en <em>-chen, -lein</em> (<em>das Mädchen, das Kätzchen</em>).</li><li><b>der</b> : en général les noms désignant spécifiquement des hommes (<em>der Vater, der Lehrer</em> ; mais <em>das Kind</em> et <em>das Baby</em> sont neutres, même pour un garçon).</li></ul><p class='callout callout--trap'>Le neutre n'est pas la catégorie « des choses » : <em>der Tisch</em> et <em>der Kaffee</em> sont masculins. Et <em>das Mädchen</em> (la fille) est neutre à cause de <em>-chen</em>, pas féminin.</p>"
  },
  "ref:g-plural": {
    title: "Le pluriel",
    sub: "-e, -er, -(e)n, -s, sans terminaison, tréma",
    body: "<p>En français, le pluriel s'écrit surtout avec un <em>-s</em> muet : à l'oral, seul l'article change (<em>le livre, les livres</em>). En allemand, le pluriel modifie souvent la forme et la prononciation du nom (certains noms restent pourtant identiques : <em>der Lehrer → die Lehrer</em>), et il existe <b>cinq schémas</b>. On ne les devine pas à coup sûr : apprenez le pluriel avec le nom (le dictionnaire le donne : <em>Tag, -e</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th>schéma</th><th>singulier</th><th>pluriel</th></tr></thead><tbody><tr><td>-e (souvent avec tréma)</td><td class='it'>der Tag, der Stuhl</td><td class='it'>die Tage, die Stühle</td></tr><tr><td>-er (tréma si possible)</td><td class='it'>das Kind, das Haus</td><td class='it'>die Kinder, die Häuser</td></tr><tr><td>-(e)n</td><td class='it'>die Frau, die Lampe</td><td class='it'>die Frauen, die Lampen</td></tr><tr><td>-s</td><td class='it'>das Auto</td><td class='it'>die Autos</td></tr><tr><td>sans terminaison</td><td class='it'>der Lehrer, der Bruder</td><td class='it'>die Lehrer, die Brüder</td></tr></tbody></table></div><ul><li><b>Tréma</b> : <em>a → ä, o → ö, u → ü, au → äu</em> (<em>der Apfel → die Äpfel</em>).</li><li>Au pluriel, l'article est <b>die</b> au nominatif et à l'accusatif, quel que soit le genre (au datif ce sera <em>den</em>, plus tard).</li><li>Les féminins en <em>-in</em> doublent le n : <em>die Lehrerin → die Lehrerinnen</em>.</li><li>La plupart des féminins prennent <em>-(e)n</em> ; le <em>-s</em> est rare, surtout pour des mots empruntés.</li></ul>"
  },
  "ref:g-artikel-nom": {
    title: "Les articles au nominatif",
    sub: "der, die, das, die ; ein, eine, ein ; kein",
    body: "<p>Le <b>nominatif</b> est le cas du sujet, et du groupe nominal attribut après <em>sein</em> : <em>Der Tisch ist neu. Das ist ein Tisch.</em> (L'adjectif attribut, <em>neu</em>, reste invariable.) C'est la forme du dictionnaire. Attention : <em>Ich bin in der Schule</em> n'est pas un attribut, c'est un groupe prépositionnel, <em>der</em> n'y est donc pas un nominatif.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>masc.</th><th>fém.</th><th>neutre</th><th>pluriel</th></tr></thead><tbody><tr><td>défini</td><td class='it'>der</td><td class='it'>die</td><td class='it'>das</td><td class='it'>die</td></tr><tr><td>indéfini</td><td class='it'>ein</td><td class='it'>eine</td><td class='it'>ein</td><td class='it'>(pas d'article)</td></tr><tr><td>négatif</td><td class='it'>kein</td><td class='it'>keine</td><td class='it'>kein</td><td class='it'>keine</td></tr></tbody></table></div><ul><li><em>ein</em> et <em>kein</em> n'ont pas de terminaison au masculin et au neutre ; le féminin prend <em>-e</em>.</li><li>Le pluriel indéfini n'existe pas : là où le français dit <em>des livres</em>, l'allemand n'a rien : <em>Das sind Bücher</em>. Même chose pour le partitif : <em>Ich trinke Kaffee</em> (je bois du café).</li><li>Pas d'élision : <em>der Apfel, die Orange</em>, jamais « l'Apfel ».</li></ul><p class='callout callout--trap'>Ne choisissez pas l'article d'après le français : <em>das Mädchen</em>, <em>der Mond</em>. Le genre, on l'apprend avec le mot.</p>"
  },
  "ref:g-artikel-akk": {
    title: "Les articles à l'accusatif",
    sub: "den, einen, keinen : seul le masculin change",
    body: "<p>L'<b>accusatif</b> marque le complément d'objet direct : <em>Ich nehme einen Kaffee. Ich sehe den Mann.</em> En français, ni le nom ni l'article ne changent selon la fonction (seuls les pronoms : <em>il, le</em>). En allemand, c'est l'article qui porte le cas, le nom reste en général identique (exception : quelques masculins dits faibles, <em>der Student → den Studenten, der Junge → den Jungen</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>masc.</th><th>fém.</th><th>neutre</th><th>pluriel</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>der / ein / kein</td><td class='it'>die / eine / keine</td><td class='it'>das / ein / kein</td><td class='it'>die / – / keine</td></tr><tr><td>accusatif</td><td class='it'><b>den / einen / keinen</b></td><td class='it'>die / eine / keine</td><td class='it'>das / ein / kein</td><td class='it'>die / – / keine</td></tr></tbody></table></div><p>Seul le <b>masculin singulier</b> change : <em>der Kaffee → den Kaffee</em>. Le féminin, le neutre et le pluriel sont identiques au nominatif :</p><ul><li><em>Ich habe einen Bruder.</em> mais <em>Ich habe eine Schwester.</em></li><li><em>Ich sehe das Auto. Ich brauche keinen Stift.</em></li><li>Au café : <em>Einen Kaffee, bitte.</em> (Un café, s'il vous plaît.)</li></ul><p class='callout callout--trap'>Les verbes <em>haben, nehmen, sehen, brauchen, trinken</em> sont suivis de l'accusatif. Penser au sujet et à l'objet : le masculin du sujet est <em>der</em>, celui de l'objet est <em>den</em>.</p>"
  },
  "ref:g-artikel-dat": {
    title: "L'article au datif",
    sub: "dem, der, dem, den + -n ; einem, einer ; meinem",
    body: "<p>Le datif est le cas qu'on emploie après certaines prépositions (<em>mit, zu, bei, aus, von, nach, seit</em>) et pour dire <em>où</em> se trouve quelque chose, mais seulement avec une préposition à double cas (<em>in, an, auf</em>…) : <em>in der Küche</em> ; les autres prépositions régissent leur propre cas. Contrairement à l'accusatif, <b>tous les genres changent</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>masc.</th><th>fém.</th><th>neutre</th><th>pluriel</th></tr></thead><tbody><tr><td>défini</td><td class='it'>dem</td><td class='it'>der</td><td class='it'>dem</td><td class='it'>den + <b>-n</b></td></tr><tr><td>indéfini</td><td class='it'>einem</td><td class='it'>einer</td><td class='it'>einem</td><td>(aucun)</td></tr><tr><td>négatif</td><td class='it'>keinem</td><td class='it'>keiner</td><td class='it'>keinem</td><td class='it'>keinen + <b>-n</b></td></tr><tr><td>possessif (mein)</td><td class='it'>meinem</td><td class='it'>meiner</td><td class='it'>meinem</td><td class='it'>meinen + <b>-n</b></td></tr></tbody></table></div><p>Exemples : <em>Ich fahre mit dem Bus. Ich wohne bei meiner Schwester. Er kommt aus der Stadt.</em></p><p>Au pluriel, le datif ajoute <b>-n</b> au nom, sauf si le pluriel se termine déjà par <em>-n</em> ou <em>-s</em> : <em>die Kinder → mit den Kindern</em>, <em>die Freunde → mit den Freunden</em>, mais <em>die Frauen → mit den Frauen</em> et <em>die Autos → mit den Autos</em>. Certains pluriels étrangers en <em>-a</em> ne le prennent pas non plus : <em>die Praktika → mit den Praktika</em>.</p><p class='callout callout--trap'>En français, la préposition ne change rien à l'article : <em>avec la femme, chez le médecin</em>. L'article varie seulement selon le genre et le nombre (et se contracte : <em>au, du</em>). En allemand, la préposition <b>demande un cas</b> et c'est l'article qui le montre : <em>mit der Frau</em>, et non <s>mit die Frau</s>. Apprends chaque préposition avec son cas (<em>mit + Dativ</em>).</p><p>Les prépositions suivies du datif ont leur propre fiche ; pour l'instant, il suffit de reconnaître la forme et de ne pas employer <em>den</em> au masculin singulier après <em>mit</em> : <em>mit dem Mann</em>.</p>"
  },
  "ref:g-genitiv": {
    title: "Le génitif",
    sub: "des Mannes, der Frau, des Kindes : le possesseur, et wegen, während, innerhalb",
    body: "<p>Le <b>génitif</b> est le quatrième cas. Il dit à qui appartient quelque chose ou de qui on parle, et se place <b>après</b> le nom auquel il se rapporte : <em>das Auto des Mannes</em> (la voiture de l'homme). L'article porte le cas :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>pluriel</th></tr></thead><tbody><tr><td>article défini</td><td class='it'>des</td><td class='it'>der</td><td class='it'>des</td><td class='it'>der</td></tr><tr><td>article indéfini</td><td class='it'>eines</td><td class='it'>einer</td><td class='it'>eines</td><td class='it'>-</td></tr><tr><td>exemple</td><td class='it'>das Auto des Mannes</td><td class='it'>die Tasche der Frau</td><td class='it'>das Spielzeug des Kindes</td><td class='it'>die Zimmer der Kinder</td></tr></tbody></table></div><p>Au masculin et au neutre, le <b>nom</b> prend aussi une terminaison : <b>-es</b> ou <b>-s</b>. En général, <em>-es</em> apparaît après les noms courts ou terminés par <em>s, ß, x, z</em> (<em>des Tages, des Hauses</em>) et <em>-s</em> après les noms plus longs (<em>des Vaters, des Computers</em>). Certains masculins faibles prennent <em>-(e)n</em> (<em>des Studenten, des Kollegen</em>). Le féminin et le pluriel ne changent pas au nom. Après l'article ou un possessif, l'adjectif au génitif prend <em>-en</em> : <em>des alten Hauses, der jungen Frau, meines neuen Autos</em>. Sans article, le masculin et le neutre ont <em>-en</em> (<em>trotz starken Regens</em>), le féminin et le pluriel <em>-er</em> (<em>wegen kalter Milch, die Hilfe guter Freunde</em>).</p><p>Les <b>noms propres</b> prennent <em>-s</em> et se placent <b>avant</b> le nom, sans article et sans apostrophe : <em>Annas Auto, Toms Bruder</em>. Si le nom finit par une sifflante (<em>-s, -ß, -x, -z</em>), on met seulement l’apostrophe : <em>Hans’ Auto, Max’ Buch</em>. À l'oral, on remplace souvent le génitif par <b>von + datif</b> : <em>das Auto von meinem Vater</em>.</p><h4>Prépositions avec le génitif</h4><div class='table-wrap'><table class='gt'><thead><tr><th>préposition</th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>wegen</td><td>à cause de</td><td class='it'>Wegen des Regens bleiben wir zu Hause.</td></tr><tr><td class='it'>während</td><td>pendant</td><td class='it'>Während des Urlaubs habe ich viel gelesen.</td></tr><tr><td class='it'>innerhalb</td><td>à l'intérieur de, dans un délai de</td><td class='it'>Innerhalb einer Woche bekommen Sie eine Antwort.</td></tr><tr><td class='it'>trotz</td><td>malgré</td><td class='it'>Trotz der Kälte gehen wir spazieren.</td></tr></tbody></table></div><p>À l'oral, après <em>wegen</em> et <em>trotz</em>, on entend souvent le datif (<em>wegen dem Wetter</em>) ; dans un texte écrit ou officiel, on emploie le génitif.</p><p class='callout callout--trap'>Le français dit la possession avec la préposition <em>de</em> (<em>la voiture du père</em>) ; l'allemand n'a pas de préposition ici : c'est l'article qui marque le <b>cas</b>, et le nom du possesseur se place, comme en français, <b>après</b> le nom possédé : <em>das Auto des Vaters</em>. Attention au faux ami : <em>des</em> allemand est l'article du masculin ou du neutre singulier, pas le <em>des</em> français du pluriel. Avec un nom propre, l'ordre s'inverse et l'on n'écrit pas d'apostrophe avant le <em>-s</em> : <em>Annas Buch</em>, pas <s>Anna's Buch</s> ; après une sifflante, l’apostrophe seule : <em>Max’ Buch</em>.</p><p class='callout callout--trap'><em>während</em> est aussi une conjonction qui envoie le verbe à la fin : <em>Während ich arbeite, ...</em>. Le français a deux mots (<em>pendant</em> et <em>pendant que</em>) ; l'allemand a un seul mot, qui change de construction. Comme préposition (<em>während des Urlaubs</em>), il se construit avec le génitif et n'est pas suivi d'un verbe conjugué.</p>"
  },
  "ref:g-n-deklination": {
    title: "La déclinaison faible des masculins",
    sub: "der Kunde, den Kunden, dem Kunden, des Kunden",
    body: "<p>Un groupe de noms <b>masculins</b> prend <b>-n</b> ou <b>-en</b> à tous les cas sauf au nominatif singulier. C'est la <b>n-Deklination</b> :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>der Kunde</th><th>der Student</th><th>der Mensch</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>der Kunde</td><td class='it'>der Student</td><td class='it'>der Mensch</td></tr><tr><td>accusatif</td><td class='it'>den Kunden</td><td class='it'>den Studenten</td><td class='it'>den Menschen</td></tr><tr><td>datif</td><td class='it'>dem Kunden</td><td class='it'>dem Studenten</td><td class='it'>dem Menschen</td></tr><tr><td>génitif</td><td class='it'>des Kunden</td><td class='it'>des Studenten</td><td class='it'>des Menschen</td></tr><tr><td>pluriel</td><td class='it'>die Kunden</td><td class='it'>die Studenten</td><td class='it'>die Menschen</td></tr></tbody></table></div><ul><li><b>masculins en -e</b> désignant des personnes ou des animaux : <em>der Kollege, der Junge, der Neffe, der Zeuge, der Löwe, der Affe</em></li><li><b>masculins d'origine étrangère</b> en <em>-ent, -ant, -ist, -at, -oge</em> : <em>der Präsident, der Praktikant, der Polizist, der Journalist, der Kandidat, der Soldat, der Biologe</em></li><li><b>quelques autres</b> : <em>der Mensch, der Herr, der Nachbar, der Bauer, der Held, der Bär</em>. <em>Herr</em> prend <em>-n</em> au singulier et <em>-en</em> au pluriel : <em>Ich schreibe Herrn Müller. Meine Damen und Herren!</em></li></ul><p>Quelques noms prennent en plus <b>-ns</b> au génitif : <em>der Name, des Namens</em> ; de même <em>der Gedanke, der Glaube, der Buchstabe</em>. <em>das Herz</em> est neutre et fait <em>dem Herzen, des Herzens</em>.</p><p>Exemples : <em>Ich habe den Kunden angerufen. Ich spreche mit dem Kollegen. Das ist das Büro des Präsidenten.</em></p><p class='callout callout--trap'>Le français ne marque pas le cas sur le nom, et le <em>-n</em> ressemble à un pluriel. <em>den Kunden</em> peut être un client (accusatif singulier) ou les clients (datif pluriel), avec le même article : c'est le cas régi par le verbe qui tranche. <em>sehen</em> régit l'accusatif, donc <em>Ich sehe den Kunden</em> désigne un client ; <em>helfen</em> régit le datif, donc <em>Ich helfe den Kunden</em> désigne les clients, et un client serait <em>Ich helfe dem Kunden</em>. L'erreur la plus fréquente est d'oublier la terminaison : <s>Ich frage den Student</s> au lieu de <em>den Studenten</em>. Les féminins ne suivent pas cette déclinaison : <em>die Kundin, der Kundin</em>.</p>"
  },
  "ref:g-wortbildung": {
    title: "Les noms composés",
    sub: "le dernier élément donne le genre : die Hand + die Tasche = die Handtasche",
    body: "<p>L'allemand fabrique des mots nouveaux en <b>collant</b> deux noms (ou plus) en un seul mot. On l'écrit d'une traite, et c'est le nom placé <b>à la fin</b> qui compte : il donne le <b>genre</b> et le sens de base, tandis que l'élément placé devant le précise.</p><div class='table-wrap'><table class='gt'><thead><tr><th>composé</th><th>formation</th><th>sens</th></tr></thead><tbody><tr><td class='it'>der Apfelsaft</td><td class='it'>der Apfel + der Saft</td><td>jus de pomme</td></tr><tr><td class='it'>die Handtasche</td><td class='it'>die Hand + die Tasche</td><td>sac à main</td></tr><tr><td class='it'>die Haustür</td><td class='it'>das Haus + die Tür</td><td>porte de la maison</td></tr><tr><td class='it'>das Wörterbuch</td><td class='it'>die Wörter + das Buch</td><td>dictionnaire</td></tr><tr><td class='it'>der Geburtstag</td><td class='it'>die Geburt + s + der Tag</td><td>anniversaire</td></tr><tr><td class='it'>das Schlafzimmer</td><td class='it'>schlafen + das Zimmer</td><td>chambre à coucher</td></tr></tbody></table></div><p>Le genre suit toujours le dernier élément : <em>die Haustür</em> est féminin parce que <em>die Tür</em> l'est, même si <em>das Haus</em> est neutre. Devant un composé nouveau, il suffit donc de regarder la fin : <em>das Zimmer → das Schlafzimmer</em>.</p><p>Entre les deux éléments apparaît parfois une petite jonction (<em>-s-, -n-, -er-</em>) : <em>Geburt<b>s</b>tag, Küche<b>n</b>tür, Kind<b>er</b>zimmer</em>. Aucune règle simple ne permet de la deviner : apprends le composé entier, avec son article. Le premier élément peut aussi être un verbe ou un adjectif (<em>das Schlafzimmer, die Großmutter</em>).</p><p class='callout callout--trap'>Le français place en général le détail <b>après</b> le nom et le relie par une préposition (<em>jus de pomme, porte de la maison, sac à main</em>). L'allemand renverse l'ordre et soude les mots : <em>der Apfelsaft</em>, pas <s>der Saft Apfel</s>. À l'écrit, ne laisse pas d'espace au milieu : <em>die Haus Tür</em> est une faute (et le trait d'union du français, comme dans <em>chou-fleur</em>, n'a pas d'équivalent ici). La dérivation par suffixes et préfixes et les composés plus longs viennent aux niveaux suivants.</p>"
  },
  "ref:g-adjektivdeklination": {
    title: "L'adjectif attribut",
    sub: "Der Pullover ist rot : aucune terminaison",
    body: "<p>Quand l'adjectif suit <em>sein</em> (ou <em>werden, bleiben</em>), il reste <b>invariable</b> : il ne s'accorde pas avec le nom en genre et en nombre.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>phrase</th></tr></thead><tbody><tr><td>masculin</td><td class='it'>Der Pullover ist rot.</td></tr><tr><td>féminin</td><td class='it'>Die Jacke ist rot.</td></tr><tr><td>neutre</td><td class='it'>Das Hemd ist rot.</td></tr><tr><td>pluriel</td><td class='it'>Die Schuhe sind rot.</td></tr></tbody></table></div><p>Autres exemples : <em>Der Mantel ist teuer. Sie ist nett. Das Zimmer ist klein. Mein Bruder ist unfreundlich.</em> Aussi avec <em>aussehen</em> : <em>Wie sieht er aus? Er sieht müde aus.</em></p><p class='callout callout--trap'>Le français accorde l'adjectif attribut (<em>il est grand, elle est grande, ils sont grands, elles sont grandes</em>) ; l'allemand attribut ne change <b>jamais</b> : <em>Die Schuhe sind rot</em>, pas <s>roten</s> ni <s>rote</s>. Quand l'adjectif se place <b>devant le nom</b> (<em>ein roter Pullover</em>), les terminaisons apparaissent : tu les vois plus bas, dans la partie A2.</p><p>Pour demander comment est quelque chose : <em>Wie ist der Pullover?</em> Pour les couleurs et les autres adjectifs de base, voir le vocabulaire des unités 4 et 8.</p><h4>A2 : l'adjectif devant le nom, après ein, kein et les possessifs</h4><p>Devant le nom, l'adjectif prend une <b>terminaison</b> qui indique le genre, le nombre et le cas. Après <em>ein, kein</em> et les possessifs (<em>mein, dein, sein ...</em>), les terminaisons sont celles-ci :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>pluriel (kein, mein)</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>ein roter Pullover</td><td class='it'>eine rote Jacke</td><td class='it'>ein rotes Hemd</td><td class='it'>keine roten Schuhe</td></tr><tr><td>accusatif</td><td class='it'>einen roten Pullover</td><td class='it'>eine rote Jacke</td><td class='it'>ein rotes Hemd</td><td class='it'>keine roten Schuhe</td></tr><tr><td>datif</td><td class='it'>einem roten Pullover</td><td class='it'>einer roten Jacke</td><td class='it'>einem roten Hemd</td><td class='it'>keinen roten Schuhen</td></tr></tbody></table></div><p>Règle pratique : là où <em>ein</em> n'a pas de terminaison (masculin nominatif, neutre nominatif et accusatif), c'est l'adjectif qui la porte (<em>-er, -es</em>) ; l'adjectif prend <em>-e</em> au féminin nominatif et accusatif, et <em>-en</em> dans tous les autres cas (datif compris). <em>mein, kein, ihr ...</em> se comportent de la même façon : <em>Das ist mein neues Handy. Ich habe keinen großen Hunger.</em> L'adjectif après <em>sein</em> reste invariable. Après <em>der, die, das</em> et sans article, les terminaisons sont dans la partie B1 ci-dessous.</p><p class='callout callout--trap'>L'adjectif français s'accorde en genre et en nombre et se place le plus souvent <b>après</b> le nom (<em>un pull rouge</em>), parfois avant (<em>un petit pull</em>). L'adjectif allemand se place normalement <b>avant</b> le nom et porte en plus le <b>cas</b> : <em>ein roter Pullover</em> (nominatif), <em>einen roten Pullover</em> (accusatif). Confondre <em>-en</em> et <em>-er</em> est l'erreur la plus fréquente.</p><h4>B1 : l'adjectif après der, die, das et sans article</h4><p>Après l'article défini (et <em>dieser, jeder, welcher</em>), la terminaison est presque toujours <b>-en</b> ; <b>-e</b> n'apparaît qu'au nominatif singulier des trois genres et à l'accusatif du féminin et du neutre :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>pluriel</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>der rote Pullover</td><td class='it'>die rote Jacke</td><td class='it'>das rote Hemd</td><td class='it'>die roten Schuhe</td></tr><tr><td>accusatif</td><td class='it'>den roten Pullover</td><td class='it'>die rote Jacke</td><td class='it'>das rote Hemd</td><td class='it'>die roten Schuhe</td></tr><tr><td>datif</td><td class='it'>dem roten Pullover</td><td class='it'>der roten Jacke</td><td class='it'>dem roten Hemd</td><td class='it'>den roten Schuhen</td></tr><tr><td>génitif</td><td class='it'>des roten Pullovers</td><td class='it'>der roten Jacke</td><td class='it'>des roten Hemds</td><td class='it'>der roten Schuhe</td></tr></tbody></table></div><p>Sans article (devant un nom sans déterminant, surtout au pluriel et avec les noms de matière), l'adjectif porte lui-même le signal de genre et de cas, avec les terminaisons de l'article : <em>-er, -e, -es, -e ; -en, -e, -es, -e ; -em, -er, -em, -en</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>pluriel</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>roter Wein</td><td class='it'>rote Milch</td><td class='it'>rotes Brot</td><td class='it'>rote Äpfel</td></tr><tr><td>accusatif</td><td class='it'>roten Wein</td><td class='it'>rote Milch</td><td class='it'>rotes Brot</td><td class='it'>rote Äpfel</td></tr><tr><td>datif</td><td class='it'>rotem Wein</td><td class='it'>roter Milch</td><td class='it'>rotem Brot</td><td class='it'>roten Äpfeln</td></tr></tbody></table></div><p>Plusieurs adjectifs devant le même nom ont la même terminaison : <em>ein großer, schöner Garten ; mit alten, neuen Freunden</em>. Après <em>ein, kein</em> et les possessifs, ce sont les terminaisons de la partie A2 ci-dessus.</p><p class='callout callout--trap'>En français, l'adjectif s'accorde en genre et en nombre (<em>rouge, rouges</em>) et c'est tout : il ne porte pas de cas. En allemand, la terminaison porte aussi le <b>cas</b>, et elle dépend de ce qui se trouve <b>avant</b> : en gros, le signal de genre et de cas apparaît une seule fois, sur l'article s'il y en a un (<em>der rote Pullover</em>, <em>-e</em> parce que <em>der</em> est déjà clair) ou sur l'adjectif s'il n'y en a pas (<em>roter Wein</em>). Après l'article défini, les terminaisons sont seulement <em>-e</em> et <em>-en</em> : ne cherche pas <em>-er</em> ou <em>-es</em>.</p><h4>C1 : adjectifs et participes substantivés</h4><p>Un adjectif ou un participe employé comme nom prend une majuscule et se décline comme un adjectif, selon l'article qui le précède :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>avec der, die, das</th><th>avec ein ou sans article</th></tr></thead><tbody><tr><td>masculin</td><td class='it'>der Bekannte</td><td class='it'>ein Bekannter</td></tr><tr><td>féminin</td><td class='it'>die Bekannte</td><td class='it'>eine Bekannte</td></tr><tr><td>pluriel</td><td class='it'>die Bekannten</td><td class='it'>Bekannte</td></tr><tr><td>datif</td><td class='it'>dem Bekannten</td><td class='it'>einem Bekannten</td></tr></tbody></table></div><p>Avec <em>kein</em>, le singulier suit <em>ein</em> (<em>kein Bekannter</em>) et le pluriel suit les possessifs (<em>keine Bekannten</em>). De même <em>der Angestellte, der Erwachsene, der Deutsche, der Reisende, der Verletzte</em>. Pour <em>etwas Neues, nichts Gutes</em>, voir l'entrée sur les pronoms indéfinis.</p><p class='callout callout--trap'>En français, <em>le connu</em> n'existe pas comme nom de personne : on dit <em>une connaissance</em>. Mais le procédé existe (<em>un blessé</em>, <em>les invités</em>), et la forme ne change pas avec l'article. En allemand la terminaison suit l'article, comme devant un nom : <em>der Bekannte</em> mais <em>ein Bekannter</em>, <em>die Deutschen</em> mais <em>viele Deutsche</em>.</p>"
  },
  "ref:g-komparation": {
    title: "Comparatif et superlatif",
    sub: "-er ... als, so ... wie, am -sten",
    body: "<p>Le comparatif de supériorité se forme avec <b>-er</b>, le superlatif attribut avec <b>am ... -sten</b>. Pour comparer on emploie <b>als</b> (supériorité et infériorité ; l'infériorité se dit <b>weniger ... als</b>, <em>weniger schön als</em>, sans <b>-er</b>), pour l'égalité <b>so ... wie</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>base</th><th>comparatif</th><th>superlatif</th></tr></thead><tbody><tr><td class='it'>klein</td><td class='it'>kleiner</td><td class='it'>am kleinsten</td></tr><tr><td class='it'>schnell</td><td class='it'>schneller</td><td class='it'>am schnellsten</td></tr><tr><td class='it'>alt</td><td class='it'>älter</td><td class='it'>am ältesten</td></tr><tr><td class='it'>jung</td><td class='it'>jünger</td><td class='it'>am jüngsten</td></tr><tr><td class='it'>groß</td><td class='it'>größer</td><td class='it'>am größten</td></tr><tr><td class='it'>gut</td><td class='it'>besser</td><td class='it'>am besten</td></tr><tr><td class='it'>viel</td><td class='it'>mehr</td><td class='it'>am meisten</td></tr><tr><td class='it'>gern</td><td class='it'>lieber</td><td class='it'>am liebsten</td></tr></tbody></table></div><p>Exemples : <em>Er ist größer als du. Sie ist so groß wie ich. Anna ist am größten. Ich trinke lieber Tee als Kaffee. Am liebsten trinke ich Wasser.</em></p><p>Beaucoup d'adjectifs courts prennent l'<b>Umlaut</b> (<em>alt, jung, groß</em>) ; <em>gut, viel, gern</em> ont des formes propres à apprendre par cœur, comme <em>bon → meilleur</em> en français.</p><p class='callout callout--trap'>Le français dit <em>que</em> dans les deux cas (<em>plus grand que toi, aussi grand que toi</em>) ; l'allemand sépare : <b>als</b> pour <em>plus ... que</em> (<em>größer als du</em>) et <b>wie</b> pour l'égalité (<em>so groß wie du</em>). Ne mets pas <em>wie</em> après un comparatif. De plus, le français ajoute <em>le</em> au superlatif (<em>le plus grand</em>) ; ici, quand il se rapporte au sujet de la phrase, on dit <em>Er ist am größten</em>.</p><p>On ne voit ici que le comparatif en position d'attribut ; devant le nom (<em>der größere Bruder</em>), il viendra avec les terminaisons de l'adjectif.</p><h4>B2 : je ... desto / umso</h4><p><b>je</b> + comparatif ouvre une subordonnée, verbe à la fin ; <b>desto</b> ou <b>umso</b> + comparatif ouvre la principale, et le verbe suit tout le groupe comparatif, y compris un éventuel nom : <em>Je mehr ich lese, desto besser verstehe ich. Je mehr ich lese, desto mehr Wörter verstehe ich. Je länger ich warte, umso nervöser werde ich.</em> Aussi en forme brève : <em>Je früher, desto besser.</em> Un nom suit directement le comparatif : <em>Je mehr Zeit ich habe, ...</em></p><p class='callout callout--trap'>Le français dit <em>plus je lis, mieux je comprends</em>, avec l'ordre normal dans les deux parties. L'allemand emploie deux mots différents (<em>je ... desto</em>) et deux ordres différents : verbe à la fin dans la première partie, verbe juste après le comparatif dans la seconde. <s>Je mehr ich lese, desto ich verstehe besser</s> est fautif.</p><h4>C1 : le très haut degré</h4><p>Pour un très haut degré sans comparaison, l'allemand place un adverbe devant l'adjectif : <em>sehr</em> et, à l'écrit, <b>höchst, äußerst, besonders, überaus</b> (<em>ein höchst interessanter Vorschlag, eine äußerst schwierige Lage</em>). À l'oral on entend aussi <em>total, echt, super</em>. Le superlatif avec <em>am</em> reste une comparaison : <em>Dieser Weg ist am kürzesten.</em> L'écrit soutenu connaît aussi <em>aufs</em> + superlatif : <em>Sie hat uns aufs Herzlichste begrüßt.</em></p><p class='callout callout--trap'>Le français dit <em>extrêmement</em>, <em>fort</em>, <em>des plus</em> (<em>une proposition des plus intéressantes</em>) : c'est le même procédé, un adverbe devant l'adjectif. Mais attention à <em>le plus</em> : <em>am schwierigsten</em> veut dire « le plus difficile » dans une comparaison, pas « très difficile », qui se dit <em>äußerst schwierig</em>.</p>"
  },
  "ref:g-possessiv": {
    title: "Les possessifs",
    sub: "mein, dein, sein, ihr, unser, euer, Ihr",
    body: "<p>Le possessif se choisit d'après le <b>possesseur</b>, puis il prend les terminaisons de <em>ein</em> selon le genre et le cas du <b>nom possédé</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>possesseur</th><th>possessif</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mein</td></tr><tr><td class='it'>du</td><td class='it'>dein</td></tr><tr><td class='it'>er</td><td class='it'>sein</td></tr><tr><td class='it'>sie (elle)</td><td class='it'>ihr</td></tr><tr><td class='it'>es</td><td class='it'>sein</td></tr><tr><td class='it'>wir</td><td class='it'>unser</td></tr><tr><td class='it'>ihr</td><td class='it'>euer</td></tr><tr><td class='it'>sie (ils, elles)</td><td class='it'>ihr</td></tr><tr><td class='it'>Sie (politesse)</td><td class='it'>Ihr</td></tr></tbody></table></div><p>Exemples : <em>Meine Mutter heißt Anna. Mein Chef ist nett. Das ist unser Haus. Ich sehe meinen Bruder.</em> Au féminin et au pluriel, au nominatif et à l'accusatif : <em>mein</em> + <b>-e</b> (<em>meine Mutter, meine Eltern</em>) ; à l'accusatif masculin <em>meinen</em> ; au datif <em>meiner Mutter, meinen Eltern</em>. <em>euer</em> perd son <em>e</em> devant une terminaison : <em>eure Mutter, euren Bruder</em>.</p><p>Avec les prénoms, le génitif se forme avec <b>-s</b> et sans apostrophe : <em>Annas Mutter, Peters Auto</em>. Si le nom finit par une sifflante (<em>-s, -x, -z, -ß</em>), on met seulement l’apostrophe : <em>Hans’ Mutter, Max’ Auto</em>. Le complément se place devant le nom, alors que le français passe par <em>de</em> (<em>la mère d'Anna</em>).</p><p class='callout callout--trap'>Le français accorde le possessif avec le nom possédé (<em>son père, sa mère, ses parents</em>) : <em>sa mère</em> peut être celle de lui ou celle d'elle. En allemand, le possesseur s'entend : <em>seine Mutter</em> est la mère de lui, <em>ihre Mutter</em> celle d'elle. Comme en français, le possessif <b>n'a pas d'article</b> devant lui : <em>mon livre</em> se dit <em>mein Buch</em>.</p><p>La forme de politesse <em>Ihr</em> s'écrit avec une majuscule, comme <em>Sie</em> : <em>Wie ist Ihr Name?</em></p>"
  },
  "ref:g-adverbien": {
    title: "Les adverbes",
    sub: "sehr, zu, viel, wenig ; immer, oft, manchmal, nie ; gut",
    body: "<h4>Degré</h4><ul><li><b>sehr</b> (très) devant l'adjectif : <em>Der Kaffee ist sehr gut.</em></li><li><b>zu</b> (trop) : <em>Die Hose ist zu klein.</em> <b>ziemlich</b> (assez), <b>ein bisschen</b> (un peu).</li><li><b>viel</b> et <b>wenig</b> après le verbe : <em>Ich arbeite viel. Er schläft wenig.</em></li></ul><h4>Fréquence</h4><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th></tr></thead><tbody><tr><td class='it'>immer</td><td>toujours</td></tr><tr><td class='it'>oft</td><td>souvent</td></tr><tr><td class='it'>manchmal</td><td>parfois</td></tr><tr><td class='it'>selten</td><td>rarement</td></tr><tr><td class='it'>nie</td><td>jamais</td></tr></tbody></table></div><p>En général, ils se placent après le verbe : <em>Ich trinke immer Kaffee.</em> S'ils ouvrent la phrase, le sujet passe après le verbe : <em>Morgens trinke ich immer Kaffee.</em></p><h4>Manière</h4><p>L'adjectif, sans terminaison, fait aussi fonction d'adverbe : <em>Er spricht gut. Sie fährt schnell. Das Kind schläft ruhig.</em> <em>gern</em> (volontiers) est lui aussi un adverbe : <em>Ich lese gern.</em></p><p class='callout callout--trap'>Le français distingue <em>bon</em> et <em>bien</em>, <em>rapide</em> et <em>rapidement</em> ; l'allemand emploie le même mot : <em>Der Kaffee ist gut</em> (il est bon) et <em>Er spricht gut</em> (il parle bien). Pour <em>très</em> et <em>beaucoup</em>, la répartition est proche de la nôtre : <b>sehr</b> avec un adjectif ou un adverbe (<em>sehr gut</em>), <b>viel</b> pour la quantité (<em>viel Zeit, Ich schlafe viel</em>) ; <s>viel gut</s> est faux. Attention à <em>nie</em> : il contient déjà la négation, donc pas de <em>nicht</em>, et rien ne correspond au <em>ne</em> de <em>ne ... jamais</em> : <em>Ich trinke nie Bier</em>.</p>"
  },
  "ref:g-personalpron": {
    title: "Les pronoms personnels sujets",
    sub: "ich, du, er, sie, es, wir, ihr, sie, Sie",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>personne</th><th>singulier</th><th>pluriel</th></tr></thead><tbody><tr><td>1</td><td class='it'>ich</td><td class='it'>wir</td></tr><tr><td>2</td><td class='it'>du</td><td class='it'>ihr</td></tr><tr><td>3</td><td class='it'>er / sie / es</td><td class='it'>sie</td></tr><tr><td>politesse</td><td class='it'>Sie</td><td class='it'>Sie</td></tr></tbody></table></div><p>Comme en français, le sujet est normalement exprimé : <em>Ich wohne in Köln</em>, jamais « Wohne in Köln » ; à l'impératif, le pronom manque pour <em>du</em> et <em>ihr</em> (<em>Komm! Kommt!</em>) mais reste pour <em>Sie</em> (<em>Kommen Sie!</em>). Des principales coordonnées peuvent omettre un sujet commun : <em>Ich gehe ins Kino und sehe einen Film.</em></p><h4>Où l'allemand diffère du français</h4><ul><li><b>vous</b> se divise en deux : <em>ihr</em> pour plusieurs amis (pluriel de <em>du</em>), <em>Sie</em> pour la politesse, au singulier comme au pluriel. Le français <em>vous</em> fait les deux tâches à la fois.</li><li><b>sie</b> veut dire trois choses : <em>elle</em> (<em>sie ist</em>), <em>ils / elles</em> (<em>sie sind</em>) et, avec une majuscule, <em>vous</em> de politesse (<em>Sie sind</em>). Seuls le verbe et la majuscule les distinguent. L'allemand n'a pas de <em>ils / elles</em> séparés.</li><li><b>er / sie / es</b> suivent le genre grammatical, pas le sens : <em>der Tisch → er, die Lampe → sie, das Buch → es</em>. Un livre n'est pas « il » mais <em>es</em>.</li><li><em>es</em> sert aussi de sujet vide : <em>Es regnet</em> (il pleut), <em>Wie geht es dir?</em></li></ul>"
  },
  "ref:g-pron-akk": {
    title: "Les pronoms à l'accusatif",
    sub: "mich, dich, ihn, sie, es, uns, euch, sie, Sie",
    body: "<p>Quand le complément d'objet direct est déjà connu, on le remplace par le pronom à l'accusatif. Changent <em>ich, du, er, wir, ihr</em> ; <em>sie, es</em> et <em>sie/Sie</em> restent identiques au nominatif.</p><div class='table-wrap'><table class='gt'><thead><tr><th>nominatif</th><th>accusatif</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mich</td></tr><tr><td class='it'>du</td><td class='it'>dich</td></tr><tr><td class='it'>er</td><td class='it'>ihn</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td></tr><tr><td class='it'>es</td><td class='it'>es</td></tr><tr><td class='it'>wir</td><td class='it'>uns</td></tr><tr><td class='it'>ihr</td><td class='it'>euch</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td></tr><tr><td class='it'>Sie</td><td class='it'>Sie</td></tr></tbody></table></div><p>Pour les choses, le pronom suit le <b>genre du nom allemand</b>, pas celui du mot français : <em>Was kostet der Pullover? Ich nehme ihn. Wie findest du die Jacke? Ich nehme sie. Das Hemd? Ich nehme es.</em> (<em>la chemise</em> est féminine en français, mais <em>das Hemd</em> est neutre : <em>es</em>.) Avec les personnes : <em>Ich sehe dich. Er ruft uns an. Ich liebe sie.</em></p><p class='callout callout--trap'>En français, le pronom complément se place <b>avant le verbe</b> (<em>je le prends, je te vois</em>). En allemand, dans une principale à l'ordre neutre, le pronom occupe la place du complément : <b>après le verbe</b>, comme un nom, et le verbe reste en deuxième position : <em>Ich nehme ihn</em>, pas <s>Ich ihn nehme</s>. Dans une subordonnée, il précède le verbe final (<em>…, weil ich ihn sehe</em>), et il peut ouvrir la phrase pour l'insistance (<em>Ihn kenne ich</em>). Il n'y a pas non plus de pronom <em>en</em> : <em>j'en prends deux</em> se dit <em>Ich nehme zwei</em>.</p>"
  },
  "ref:g-pron-dat": {
    title: "Les pronoms personnels au datif",
    sub: "mir, dir, ihm, ihr, ihm, uns, euch, ihnen",
    body: "<p>Le datif est le cas du <b>complément d'attribution</b> (<em>à qui ?</em>) et de certains verbes qui le demandent toujours. Après le nominatif et l'accusatif, voici les trois formes côte à côte.</p><div class='table-wrap'><table class='gt'><thead><tr><th>nominatif</th><th>accusatif</th><th>datif</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mich</td><td class='it'>mir</td></tr><tr><td class='it'>du</td><td class='it'>dich</td><td class='it'>dir</td></tr><tr><td class='it'>er</td><td class='it'>ihn</td><td class='it'>ihm</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td><td class='it'>ihr</td></tr><tr><td class='it'>es</td><td class='it'>es</td><td class='it'>ihm</td></tr><tr><td class='it'>wir</td><td class='it'>uns</td><td class='it'>uns</td></tr><tr><td class='it'>ihr</td><td class='it'>euch</td><td class='it'>euch</td></tr><tr><td class='it'>sie</td><td class='it'>sie</td><td class='it'>ihnen</td></tr><tr><td class='it'>Sie</td><td class='it'>Sie</td><td class='it'>Ihnen</td></tr></tbody></table></div><p>Exemples : <em>Ich gebe ihm das Buch. Wir schicken dir eine Nachricht. Das Kleid gefällt ihr. Ich helfe Ihnen gern.</em> Le datif apparaît aussi dans des expressions de sensation et d'état : <em>Wie geht es dir? Mir ist kalt. Mir geht es gut.</em></p><p>Dans la principale neutre, le pronom se place après le verbe conjugué, dans le champ central ; dans la subordonnée, il précède le verbe (<em>..., weil ich ihm helfe</em>). Quand la phrase contient aussi un objet à l'accusatif, l'ordre dépend du type de mot (voir la fiche sur l'ordre des mots) : <em>Ich gebe ihm das Buch. Ich gebe es ihm.</em></p><p class='callout callout--trap'>Le français a des pronoms clitiques placés avant le verbe (<em>me, te, lui, leur</em>) : <em>je lui donne le livre</em>. L'allemand a des mots séparés qui, dans la principale neutre, viennent <b>après</b> le verbe : <em>Ich gebe ihm das Buch</em>, pas <s>Ich ihm gebe das Buch</s> ; dans la subordonnée ils précèdent le verbe final (<em>..., weil ich es ihm gebe</em>). Le français <em>lui</em> sert pour un homme comme pour une femme ; l'allemand distingue <em>ihm</em> (masculin et neutre) et <em>ihr</em> (féminin). À l'inverse, <em>me</em> et <em>te</em> couvrent l'accusatif et le datif, alors que l'allemand sépare <em>mich / mir</em> et <em>dich / dir</em>. Attention aussi aux mots identiques à fonction différente : <em>ihr</em> est aussi le pronom <em>vous</em> au nominatif (<em>Ihr seid müde</em>), et <em>ihnen</em> (à eux, à elles) ne se confond pas avec <em>Ihnen</em> (à vous, de politesse, avec une majuscule).</p>"
  },
  "ref:g-indefinitpron": {
    title: "einer, eins, welche, keiner",
    sub: "pronoms qui remplacent un nom déjà mentionné",
    body: "<p>Pour ne pas répéter un nom, on emploie des formes de <em>ein</em>, <em>kein</em> et <em>welche</em> sans le nom. La terminaison montre le genre et le cas.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>masc.</th><th>fém.</th><th>neutre</th><th>pluriel</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>einer</td><td class='it'>eine</td><td class='it'>eins</td><td class='it'>welche</td></tr><tr><td>accusatif</td><td class='it'>einen</td><td class='it'>eine</td><td class='it'>eins</td><td class='it'>welche</td></tr><tr><td>négatif (nom.)</td><td class='it'>keiner</td><td class='it'>keine</td><td class='it'>keins</td><td class='it'>keine</td></tr><tr><td>négatif (acc.)</td><td class='it'>keinen</td><td class='it'>keine</td><td class='it'>keins</td><td class='it'>keine</td></tr></tbody></table></div><p>Exemples : <em>Ich brauche einen Stuhl. Haben Sie einen? Ja, ich habe einen. Haben Sie Brötchen? Ja, wir haben welche. Nein, wir haben keine. Ein Bier? Ich nehme eins.</em></p><p>Avec un nombre, le nombre suffit : <em>Ich nehme zwei.</em> <b>welche</b> remplace un nom pluriel déjà connu : <em>Hast du Brötchen? Ja, ich habe welche.</em> (<em>Tu as des petits pains ? Oui, j'en ai.</em>). Un nom singulier non comptable prend une forme accordée : <em>Hast du Milch? Ja, ich habe welche.</em> (féminin), <em>Hast du Geld? Ja, ich habe welches.</em> (neutre). Le nom sans article reste possible quand on le nomme : <em>Ich kaufe Brötchen.</em></p><p class='callout callout--trap'>Le français résout tout avec <em>en</em> (<em>j'en ai, tu en veux ?</em>), un seul pronom pour les deux genres et les deux nombres. L'allemand n'a pas de pronom équivalent : il emploie un pronom qui s'accorde avec le nom sous-entendu, et <em>welche</em> (et <em>welches</em> au neutre) correspond à <em>en</em> pour un pluriel ou une quantité non précisée : <em>Hast du einen Bruder? Ja, ich habe einen.</em> (<em>Oui, j'en ai un.</em>) Au neutre la forme est <em>eins</em> (à l'écrit aussi <em>eines</em>). Les formes avec <em>jemand, jeder, etwas</em> sont dans la partie B1 ci-dessous.</p><h4>B1 : jemand, niemand, jeder, etwas, nichts</h4><p>Ces pronoms ne renvoient pas à un nom déjà mentionné : ils parlent de personnes ou de choses de façon générale.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>pour tous</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>jeder</td><td class='it'>jede</td><td class='it'>jedes</td><td class='it'>jemand, niemand</td></tr><tr><td>accusatif</td><td class='it'>jeden</td><td class='it'>jede</td><td class='it'>jedes</td><td class='it'>jemand(en), niemand(en)</td></tr><tr><td>datif</td><td class='it'>jedem</td><td class='it'>jeder</td><td class='it'>jedem</td><td class='it'>jemand(em), niemand(em)</td></tr></tbody></table></div><p><b>jemand</b> (quelqu'un) et <b>niemand</b> (personne) peuvent rester invariables ou prendre <em>-en</em> à l'accusatif et <em>-em</em> au datif : <em>Ich habe niemanden gesehen / Ich habe niemand gesehen. Ich habe jemandem geholfen.</em> <b>jeder</b> (chacun) est <b>singulier</b> et se décline comme <em>dieser</em> : <em>Jeder weiß das. Ich kenne jeden hier.</em> <b>alle</b> est pluriel : <em>Alle sind da.</em></p><p><b>etwas</b> (quelque chose) et <b>nichts</b> (rien) ne changent pas ; un adjectif qui les suit prend une majuscule et, au nominatif et à l'accusatif, la terminaison <em>-es</em> (<em>etwas Neues, nichts Besonderes</em>), au datif <em>-em</em> (<em>mit etwas Neuem, mit nichts Besonderem</em>). Pour <em>quelqu'un d'autre</em>, on dit <em>jemand anders</em>.</p><p class='callout callout--trap'>Avec <em>personne</em> et <em>rien</em> après le verbe, le français standard met <em>ne</em> (<em>Je n'ai vu personne, je n'ai rien fait</em>). L'allemand non : <em>Ich habe niemanden gesehen. Ich habe nichts gemacht</em>, jamais <s>Ich habe nicht niemanden gesehen</s>. Et <em>jeder</em> est singulier comme <em>chacun</em> (<em>Jeder hat seine Meinung</em>), alors que <em>alle</em> est pluriel comme <em>tous</em>.</p>"
  },
  "ref:g-es": {
    title: "es gibt, es regnet, es geht",
    sub: "es sans sens propre",
    body: "<p>Dans beaucoup de phrases allemandes, le sujet <em>es</em> ne désigne pas une chose, mais il est nécessaire : en règle générale, la phrase demande un sujet exprimé.</p><h4>es gibt (il y a)</h4><p>La forme est <b>toujours au singulier</b>, et après <em>gibt</em> le nom se met à l'<b>accusatif</b> : <em>Es gibt einen Bahnhof. Es gibt keinen Supermarkt hier. Es gibt drei Kinos in der Stadt.</em> Question : <em>Gibt es hier ein Café?</em></p><h4>Temps, heure, états</h4><ul><li><em>Es regnet. Es schneit. Es ist kalt. Es ist heiß.</em></li><li><em>Es ist Montag. Wie spät ist es? Es ist acht Uhr.</em></li><li><em>Wie geht's? Es geht.</em></li></ul><p class='callout callout--trap'>Ici le français est proche : il a lui aussi un sujet vide (<em>il pleut, il est tard, il y a</em>), et <em>es</em> ne s'omet pas : <em>Es regnet</em>, pas <s>Regnet</s>. Les pièges sont ailleurs : <em>il fait froid</em> se dit avec <em>sein</em> (<em>Es ist kalt</em>), et après <em>es gibt</em> il faut l'accusatif (<em>einen Bahnhof</em>). <em>es gibt</em> introduit en général quelque chose de nouveau, donc avec <em>ein, kein</em> ou sans article (<em>Es gibt ein Café</em>) ; pour situer une chose déjà connue, on emploie <em>sein</em> (<em>Wo ist das Café? Es ist neben der Post.</em>).</p><p>Les emplois de <em>es</em> comme élément provisoire ou comme renvoi à une subordonnée viennent beaucoup plus tard.</p><h4>C1 : es qui annonce une proposition</h4><p>Quand une proposition avec <em>dass</em>, <em>ob</em> ou un infinitif avec <em>zu</em> est sujet ou complément, la principale peut contenir <b>es</b> comme annonce : <em>Es freut mich, dass du kommst. Ich finde es gut, dass du fragst. Es ist wichtig, pünktlich zu sein.</em> Si la proposition passe en tête, l'annonce du sujet disparaît : <em>Dass du kommst, freut mich.</em> Avec les verbes à préposition, l'annonce est <em>darauf, daran, dafür</em> (voir l'entrée sur les verbes à préposition).</p><p class='callout callout--trap'>Le français connaît ce procédé avec <em>il</em> : <em>il est important d'être ponctuel</em> = <em>Es ist wichtig, pünktlich zu sein</em>. En position de complément, en revanche, il n'emploie pas de pronom (<em>je trouve bien que tu demandes</em>), alors que l'allemand met volontiers <em>es</em> : <em>Ich finde es gut, dass ...</em></p>"
  },
  "ref:g-man": {
    title: "Le sujet impersonnel man",
    sub: "Man spricht Deutsch : man + 3e personne du singulier",
    body: "<p><b>man</b> est un pronom qui désigne une personne quelconque, les gens en général : <em>on</em>, <em>quelqu'un</em>, <em>n'importe qui</em>. On l'emploie pour les règles, les habitudes et les consignes, quand peu importe qui agit.</p><p><em>Man spricht hier Deutsch. Man darf hier nicht rauchen. Wie sagt man das auf Deutsch? In Italien isst man spät zu Abend.</em></p><p>Le verbe est toujours à la <b>3e personne du singulier</b>, même quand le sens est pluriel (<em>man sagt</em>, pas <s>man sagen</s>). Le pronom a trois formes, qui suivent le modèle de <em>ein</em> :</p><div class='table-wrap'><table class='gt'><thead><tr><th>cas</th><th>forme</th><th>exemple</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>man</td><td class='it'>Man kann hier parken.</td></tr><tr><td>accusatif</td><td class='it'>einen</td><td class='it'>Das ärgert einen.</td></tr><tr><td>datif</td><td class='it'>einem</td><td class='it'>Dort hilft einem jeder.</td></tr></tbody></table></div><p>Le possessif correspondant est <em>sein</em> et le réfléchi <em>sich</em> : <em>Man muss seine Hausaufgaben machen. Man sollte sich Zeit nehmen.</em></p><p class='callout callout--trap'><b>man</b> est le meilleur équivalent de <em>on</em> : <em>On parle allemand ici</em> se dit <em>Man spricht hier Deutsch</em>, et dans les deux langues le verbe reste à la 3e personne du singulier. Mais <b>man</b> n'est pas <b>der Mann</b> (l'homme) : l'écriture est presque la même, pourtant <em>man</em> n'a qu'un seul <em>n</em> et pas de majuscule. Autre différence : le <em>on</em> français sert très souvent de <em>nous</em> à l'oral (<em>on y va</em>), alors que l'allemand dit d'ordinaire <em>wir</em> (<em>Wir gehen</em>) ; <em>man</em> ne remplace <em>wir</em> que dans quelques emplois (<em>Man trifft sich um acht</em>). Enfin, le français n'a qu'une forme <em>on</em> (avec <em>se, soi</em> pour le réfléchi), alors que l'allemand décline <em>man / einen / einem</em>.</p>"
  },
  "ref:g-praesens": {
    title: "Le présent",
    sub: "-e, -st, -t, -en, -t, -en ; sein, haben ; e → i / ie, a → ä",
    body: "<p>On retire <em>-en</em> de l'infinitif et on ajoute la terminaison. Contrairement au français, où plusieurs terminaisons sont muettes (<em>je parle, tu parles, il parle</em> sonnent pareil), en allemand elles se prononcent toutes et indiquent la personne.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>wohnen</th><th>arbeiten</th><th>essen</th><th>sein</th><th>haben</th></tr></thead><tbody><tr><td>ich</td><td class='it'>wohne</td><td class='it'>arbeite</td><td class='it'>esse</td><td class='it'>bin</td><td class='it'>habe</td></tr><tr><td>du</td><td class='it'>wohnst</td><td class='it'>arbeitest</td><td class='it'>isst</td><td class='it'>bist</td><td class='it'>hast</td></tr><tr><td>er/sie/es</td><td class='it'>wohnt</td><td class='it'>arbeitet</td><td class='it'>isst</td><td class='it'>ist</td><td class='it'>hat</td></tr><tr><td>wir</td><td class='it'>wohnen</td><td class='it'>arbeiten</td><td class='it'>essen</td><td class='it'>sind</td><td class='it'>haben</td></tr><tr><td>ihr</td><td class='it'>wohnt</td><td class='it'>arbeitet</td><td class='it'>esst</td><td class='it'>seid</td><td class='it'>habt</td></tr><tr><td>sie/Sie</td><td class='it'>wohnen</td><td class='it'>arbeiten</td><td class='it'>essen</td><td class='it'>sind</td><td class='it'>haben</td></tr></tbody></table></div><ul><li>Les verbes comme <em>machen</em> suivent le schéma sans exception. Infinitifs en <b>-eln</b> : <em>sammeln → ich sammle, wir sammeln</em> (le <em>-e</em> du radical tombe devant <em>-e</em>, et <em>wir / sie</em> prennent seulement <em>-n</em>). Infinitifs en <b>-ern</b> : <em>wandern → ich wandere, wir wandern</em> (le <em>-e</em> se garde normalement ; une variante <em>ich wandre</em> existe).</li><li>Radical en <b>-t / -d</b> : un <em>-e-</em> s'intercale pour la prononciation : <em>du arbeitest, er arbeitet, ihr arbeitet</em> ; de même <em>finden → du findest</em>. Avec changement de voyelle, c'est autre chose : <em>du hältst, du lädst</em>.</li><li>Radical en <b>-s, -ß, -z</b> : à <em>du</em> la terminaison est <em>-t</em> : <em>du heißt, du tanzt</em>.</li><li><b>Changement de voyelle</b> à <em>du</em> et <em>er/sie/es</em> seulement : <em>essen → du isst</em>, <em>nehmen → nimmt</em>, <em>sprechen → spricht</em>, <em>sehen → sieht</em>, <em>fahren → fährt</em>, et <em>halten → hältst, hält</em>, <em>laden → lädst, lädt</em> (comme <em>je viens, nous venons</em>, mais uniquement à ces deux personnes).</li></ul><p>Le présent allemand couvre aussi « être en train de » : <em>Ich esse</em> = je mange / je suis en train de manger. Pour dire qu'on aime faire quelque chose : <em>gern</em> : <em>Ich esse gern Pizza.</em></p>"
  },
  "ref:g-modalverben": {
    title: "Les verbes modaux",
    sub: "können, wollen, müssen, möchte ; cadre verbal",
    body: "<p>Les modaux expriment la capacité (<em>können</em>), la volonté (<em>wollen</em>), l'obligation (<em>müssen</em>) et le souhait poli (<em>möchte</em>). Ils ont leur propre conjugaison : avec <em>können, wollen, müssen</em>, la 1re et la 3e personne du singulier sont <b>identiques et sans terminaison</b> (<em>ich kann, er kann</em>). <em>möchte</em> fait exception : il a <em>-e</em> (<em>ich möchte, er möchte</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>können</th><th>wollen</th><th>müssen</th><th>möchten</th></tr></thead><tbody><tr><td>ich</td><td class='it'>kann</td><td class='it'>will</td><td class='it'>muss</td><td class='it'>möchte</td></tr><tr><td>du</td><td class='it'>kannst</td><td class='it'>willst</td><td class='it'>musst</td><td class='it'>möchtest</td></tr><tr><td>er/sie/es</td><td class='it'>kann</td><td class='it'>will</td><td class='it'>muss</td><td class='it'>möchte</td></tr><tr><td>wir</td><td class='it'>können</td><td class='it'>wollen</td><td class='it'>müssen</td><td class='it'>möchten</td></tr><tr><td>ihr</td><td class='it'>könnt</td><td class='it'>wollt</td><td class='it'>müsst</td><td class='it'>möchtet</td></tr><tr><td>sie/Sie</td><td class='it'>können</td><td class='it'>wollen</td><td class='it'>müssen</td><td class='it'>möchten</td></tr></tbody></table></div><p>Le modal est en <b>deuxième position</b>, l'infinitif va <b>à la fin de la phrase</b> : <em>Ich kann heute nicht kommen. Ich muss um sieben aufstehen. Wir wollen am Samstag ins Kino gehen.</em> Le modal et l'infinitif forment un <b>cadre</b> qui enserre le reste de la phrase.</p><p><em>möchte</em> est à l'origine une forme de politesse de <em>mögen</em> (Konjunktiv II) ; à ce niveau, c'est une formule pour les demandes et les souhaits polis, proche de <em>je voudrais</em> : <em>Ich möchte einen Kaffee.</em> (l'infinitif peut être omis). Au restaurant, <em>Ich hätte gern das Schnitzel</em> est aussi une formule figée.</p><p class='callout callout--trap'>En français l'infinitif suit directement le modal (<em>je peux venir aujourd'hui</em>), et le parallèle avec l'allemand s'arrête là : en allemand l'infinitif part à la fin. Même dans une phrase courte (<em>Ich kann heute kommen</em>) il est en dernière position ; avec plusieurs compléments, le cadre se voit mieux : <em>Ich kann heute Abend mit dir ins Kino gehen</em>, et <s>Ich kann gehen heute Abend ins Kino</s> est une erreur. Après le modal, pas de <em>zu</em> devant l'infinitif, comme en français pas de <em>à</em> ni de <em>de</em>. Il existe aussi <em>dürfen</em> et <em>sollen</em>, qui viennent plus tard.</p><h4>B2 : le double infinitif</h4><p>Au Perfekt et au Konjunktiv II passé, un verbe de modalité accompagné d'un autre verbe ne prend pas son participe (<em>gekonnt, gemusst</em>) mais son <b>infinitif</b> : la phrase se termine par deux infinitifs, d'abord le verbe principal, puis le verbe de modalité. L'auxiliaire est toujours <b>haben</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>exemple</th></tr></thead><tbody><tr><td>Perfekt</td><td class='it'>Ich habe gestern nicht kommen können.</td></tr><tr><td>Konjunktiv II passé</td><td class='it'>Ich hätte dich früher anrufen sollen.</td></tr><tr><td>reproche</td><td class='it'>Du hättest es mir sagen müssen.</td></tr><tr><td>subordonnée</td><td class='it'>..., weil ich nicht hätte kommen dürfen.</td></tr></tbody></table></div><p>Dans la subordonnée, l'auxiliaire ne va pas à la fin : il se place <b>devant les deux infinitifs</b> (<em>..., dass er nicht hat kommen können</em>). Quand le verbe de modalité est seul, sans autre verbe, il prend son participe normal : <em>Ich habe das nicht gekonnt.</em></p><p class='callout callout--trap'>Le français dit <em>j'aurais dû appeler</em>, <em>tu aurais pu me le dire</em> : auxiliaire, participe du modal, puis infinitif. L'allemand garde l'auxiliaire conjugué mais met le modal à la fin, à l'infinitif : <em>Ich hätte anrufen sollen</em>. Calquer le français donne <s>Ich hätte gesollt anrufen</s>, qui n'existe pas.</p><h4>C1 : l'emploi subjectif des modaux</h4><p>En plus de leur sens de base, les modaux indiquent à quel point le locuteur est sûr de lui, ou d'où vient une information :</p><div class='table-wrap'><table class='gt'><thead><tr><th>modal</th><th>valeur</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>muss</td><td>presque certain</td><td class='it'>Er muss zu Hause sein, das Licht ist an.</td></tr><tr><td class='it'>dürfte</td><td>probable</td><td class='it'>Das dürfte reichen.</td></tr><tr><td class='it'>kann, könnte</td><td>possible</td><td class='it'>Sie könnte recht haben.</td></tr><tr><td class='it'>soll</td><td>d'autres le disent</td><td class='it'>Der Film soll gut sein.</td></tr><tr><td class='it'>will</td><td>il l'affirme lui-même, le locuteur en doute</td><td class='it'>Er will nichts gesehen haben.</td></tr></tbody></table></div><p>Pour une supposition sur le passé, le modal reste au présent et l'infinitif change : <em>Er muss den Schlüssel vergessen haben.</em></p><p class='callout callout--trap'>Le français connaît cet emploi avec <em>devoir</em> et <em>pouvoir</em> (<em>il doit être à la maison</em>, <em>elle pourrait avoir raison</em>), mais pas d'équivalent direct de <em>soll</em> et <em>will</em> : <em>Der Film soll gut sein</em>, c'est « le film serait bon » ou « il paraît que le film est bon », <em>Er will nichts gesehen haben</em>, « il prétend n'avoir rien vu ». Et ici <em>dürfte</em> n'a rien à voir avec la permission : il signifie « probablement ».</p>"
  },
  "ref:g-trennbare-verben": {
    title: "Les verbes à particule séparable",
    sub: "aufstehen : Ich stehe um sieben auf",
    body: "<p>Beaucoup de verbes ont un préfixe accentué qui, dans la proposition principale, <b>se détache</b> et va à la fin de la phrase. L'infinitif reste uni.</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitif</th><th>présent</th></tr></thead><tbody><tr><td class='it'>aufstehen</td><td class='it'>Ich stehe um sieben auf.</td></tr><tr><td class='it'>einkaufen</td><td class='it'>Wir kaufen am Samstag ein.</td></tr><tr><td class='it'>anrufen</td><td class='it'>Ich rufe dich an.</td></tr><tr><td class='it'>fernsehen</td><td class='it'>Er sieht abends fern.</td></tr><tr><td class='it'>mitkommen</td><td class='it'>Kommst du mit?</td></tr><tr><td class='it'>ankommen</td><td class='it'>Der Zug kommt um acht an.</td></tr></tbody></table></div><p>Avec un modal, le verbe revient entier, à la fin : <em>Ich muss um sieben aufstehen. Ich möchte heute einkaufen.</em> Les deux parties encadrent la phrase, comme le cadre du modal.</p><p class='callout callout--trap'>Le français n'a pas de préfixe qui se détache : <em>se lever, appeler, acheter</em> restent d'un seul bloc. En allemand, c'est la structure normale : <em>Ich stehe auf</em>, avec <em>auf</em> tout au bout. <em>aufstehen</em> correspond à <em>se lever</em>, qui est pronominal en français : en allemand le verbe <b>ne demande aucun pronom</b> : <em>Ich stehe auf</em>, pas <s>Ich stehe mich auf</s>. Le changement de voyelle reste dans le verbe : <em>fernsehen → er sieht fern</em>, <em>einladen → er lädt ein</em>.</p><p>Préfixes séparables courants : <em>auf-, an-, ein-, mit-, aus-, fern-, zurück-</em>. Ils sont toujours accentués : <em>'aufstehen, 'anrufen</em>.</p><p class='callout callout--trap'>Les préfixes <b>inséparables</b> (<em>be-, ver-, er-, ent-, ge-</em>) ne sont pas accentués et <b>ne se détachent pas</b> : <em>besuchen → Ich besuche dich</em>, <em>verstehen → Ich verstehe das</em>, <em>bekommen → Er bekommt ein Geschenk</em>. Le Partizip II ne prend pas <em>ge-</em> (<em>besucht, verstanden, bekommen</em>). Les préfixes <em>über-, um-, unter-, durch-</em> peuvent être dans les deux cas : on les voit plus tard.</p><h4>C1 : préfixes séparables ou inséparables</h4><p>Les préfixes <b>durch-, über-, um-, unter-, wieder-</b> peuvent être séparables ou inséparables, et le sens change souvent. Séparable : accent sur le préfixe, préfixe détaché aux formes conjuguées et, si le verbe de base prend <em>ge-</em>, participe avec <em>-ge-</em> au milieu (<em>umgefahren</em>) ; en général un sens concret. Inséparable : accent sur le radical, préfixe toujours attaché, participe sans <em>ge-</em> ; souvent un sens figuré.</p><div class='table-wrap'><table class='gt'><thead><tr><th>séparable</th><th>inséparable</th></tr></thead><tbody><tr><td class='it'>Er hat das Schild umgefahren.</td><td class='it'>Wir haben den Stau umfahren.</td></tr><tr><td>il a renversé le panneau en voiture</td><td>nous avons contourné l'embouteillage</td></tr><tr><td class='it'>Die Fähre setzt uns über.</td><td class='it'>Sie hat den Text übersetzt.</td></tr><tr><td>le bac nous fait traverser</td><td>elle a traduit le texte</td></tr><tr><td class='it'>Wir sind die ganze Nacht durchgefahren.</td><td class='it'>Wir haben die Schweiz in drei Stunden durchfahren.</td></tr><tr><td>nous avons roulé toute la nuit sans nous arrêter</td><td>nous avons traversé la Suisse</td></tr></tbody></table></div><p class='callout callout--trap'>À l'infinitif, les deux formes s'écrivent de la même façon (<em>umfahren</em>) et seul l'accent les distingue ; aux autres formes, la séparation du préfixe et le participe aident aussi. Le français n'a rien de comparable : les paires s'apprennent une par une.</p>"
  },
  "ref:g-imperativ": {
    title: "L'impératif de politesse",
    sub: "Gehen Sie geradeaus !",
    body: "<p>Avec <b>Sie</b>, l'impératif se forme avec l'<b>infinitif + Sie</b> : le verbe est en première position et le pronom vient juste après.</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitif</th><th>impératif</th></tr></thead><tbody><tr><td class='it'>gehen</td><td class='it'>Gehen Sie geradeaus!</td></tr><tr><td class='it'>nehmen</td><td class='it'>Nehmen Sie die erste Straße links!</td></tr><tr><td class='it'>abbiegen</td><td class='it'>Biegen Sie rechts ab!</td></tr><tr><td class='it'>warten</td><td class='it'>Warten Sie bitte!</td></tr><tr><td class='it'>entschuldigen</td><td class='it'>Entschuldigen Sie, wo ist der Bahnhof?</td></tr></tbody></table></div><p>Les verbes séparables envoient le préfixe à la fin : <em>Biegen Sie rechts ab. Steigen Sie hier aus.</em> Exception : <em>sein</em> donne <b>Seien Sie</b> (<em>Seien Sie bitte pünktlich!</em>), et non <s>Sind Sie</s>. Pour les indications de chemin, il faut aussi <em>geradeaus, links, rechts, die erste, die zweite Straße</em>.</p><p class='callout callout--trap'>En français, l'impératif de politesse se fait avec la forme en <em>-ez</em> et <b>sans pronom</b> (<em>Allez tout droit ! Prenez la première à gauche !</em>). En allemand, le pronom reste, après le verbe : <em>Gehen Sie!</em> Le <em>vous</em> de politesse français correspond à <em>Sie</em> (et jamais à <em>ihr</em>, qui est le pluriel de <em>du</em>). L'impératif a la même forme qu'une question oui/non (verbe en première position suivi de <em>Sie</em>) : <em>Gehen Sie geradeaus!</em> ou <em>Gehen Sie geradeaus?</em> Le français change la forme (<em>Allez-vous tout droit ?</em>), l'allemand non : ce sont le contexte, l'intonation et, à l'écrit, la ponctuation qui les distinguent. Une demande polie peut aussi se terminer par un point, pas seulement par un point d'exclamation.</p><h4>A2 : l'impératif avec du et ihr</h4><p>Avec <b>du</b>, on emploie le radical du verbe, sans <em>-st</em> et <b>sans pronom</b> : <em>Komm! Mach das bitte! Sei ruhig!</em> Avec <b>ihr</b>, on emploie la forme du présent, toujours sans pronom : <em>Kommt! Macht das bitte! Seid ruhig!</em></p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitif</th><th>Sie</th><th>du</th><th>ihr</th></tr></thead><tbody><tr><td class='it'>gehen</td><td class='it'>Gehen Sie!</td><td class='it'>Geh!</td><td class='it'>Geht!</td></tr><tr><td class='it'>warten</td><td class='it'>Warten Sie!</td><td class='it'>Warte!</td><td class='it'>Wartet!</td></tr><tr><td class='it'>nehmen</td><td class='it'>Nehmen Sie!</td><td class='it'>Nimm!</td><td class='it'>Nehmt!</td></tr><tr><td class='it'>lesen</td><td class='it'>Lesen Sie!</td><td class='it'>Lies!</td><td class='it'>Lest!</td></tr><tr><td class='it'>fahren</td><td class='it'>Fahren Sie!</td><td class='it'>Fahr!</td><td class='it'>Fahrt!</td></tr><tr><td class='it'>aufstehen</td><td class='it'>Stehen Sie auf!</td><td class='it'>Steh auf!</td><td class='it'>Steht auf!</td></tr><tr><td class='it'>sein</td><td class='it'>Seien Sie!</td><td class='it'>Sei!</td><td class='it'>Seid!</td></tr></tbody></table></div><p>Trois particularités : les verbes faibles à radical en <em>-t, -d</em> ont normalement <em>-e</em> (<em>Warte! Arbeite!</em>), alors que les forts sont différents (<em>Tritt! Halt!</em> ; <em>Lad!</em> ou <em>Lade!</em>) ; les verbes à changement <em>e → i/ie</em> le gardent à la forme <em>du</em> (<em>Nimm! Lies! Sprich langsamer!</em>), alors que le changement <em>a → ä</em> n'a pas lieu (<em>Fahr!</em>) ; dans les verbes séparables, le préfixe va à la fin (<em>Steh auf!</em>).</p><p class='callout callout--trap'>Le français a une seule forme pour <em>vous</em> (<em>Venez !</em>), qui sert pour plusieurs amis comme pour la politesse ; l'allemand sépare <em>Kommt!</em> (<em>ihr</em>) et <em>Kommen Sie!</em> (<em>Sie</em>). Pour <em>tu</em>, le français supprime le <em>-s</em> des verbes en <em>-er</em> (<em>mange !</em>) alors que l'allemand ôte <em>-st</em> et ne garde que le radical : <em>Geh!</em> L'impératif de <em>sein</em> ressemble au français : <em>sois, soyez</em> donnent <em>Sei!, Seid!</em> Pour interdire, le français encadre le verbe (<em>Ne fume pas !</em>) : en allemand, le verbe reste à l'impératif et on ajoute <em>nicht</em> après lui : <em>Rauch nicht! Geht nicht allein!</em> Pour adoucir la demande, on ajoute <em>bitte</em> ou <em>mal</em> : <em>Komm mal her!</em></p>"
  },
  "ref:g-perfekt": {
    title: "Le Perfekt",
    sub: "haben/sein + participe II",
    body: "<p>À l'oral, le passé se fait avec le <b>Perfekt</b> : l'auxiliaire (<em>haben</em> ou <em>sein</em>) en deuxième position et le <b>participe II</b> à la fin de la phrase.</p><p><em>Ich habe gegessen. Wir haben einen Film gesehen. Ich bin nach Berlin gefahren. Sie ist früh aufgestanden.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>infinitif</th><th>participe II</th></tr></thead><tbody><tr><td>régulier : ge- ... -t</td><td class='it'>machen</td><td class='it'>gemacht</td></tr><tr><td></td><td class='it'>kaufen</td><td class='it'>gekauft</td></tr><tr><td>fort : ge- ... -en</td><td class='it'>essen</td><td class='it'>gegessen</td></tr><tr><td></td><td class='it'>sehen</td><td class='it'>gesehen</td></tr><tr><td>avec sein</td><td class='it'>fahren</td><td class='it'>gefahren</td></tr><tr><td></td><td class='it'>gehen</td><td class='it'>gegangen</td></tr><tr><td></td><td class='it'>kommen</td><td class='it'>gekommen</td></tr><tr><td>séparable : ge- au milieu</td><td class='it'>aufstehen</td><td class='it'>aufgestanden</td></tr><tr><td></td><td class='it'>einkaufen</td><td class='it'>eingekauft</td></tr><tr><td>sans ge-</td><td class='it'>studieren</td><td class='it'>studiert</td></tr><tr><td></td><td class='it'>besuchen</td><td class='it'>besucht</td></tr></tbody></table></div><p>Le participe des verbes forts s'apprend avec l'infinitif (<em>trinken, getrunken ; schreiben, geschrieben</em>). Ne prennent pas <em>ge-</em> les verbes en <em>-ieren</em> et ceux qui ont un préfixe inséparable (<em>be-, ver-, er-</em>).</p><p>On emploie <b>sein</b> avec les verbes intransitifs de <b>changement de lieu ou d'état</b> (<em>fahren, gehen, kommen, fliegen, aufstehen</em>) et avec <em>sein, bleiben, werden, passieren</em> ; avec presque tous les autres, <b>haben</b>. Un verbe de mouvement employé transitivement, avec un COD à l'accusatif, prend <em>haben</em> : <em>Ich habe das Auto gefahren.</em> Un complément au datif ne change pas l'auxiliaire : <em>Ich bin ihm gefolgt.</em> Pour <em>sein</em> et <em>haben</em> eux-mêmes, on préfère <em>war</em> et <em>hatte</em> : <em>Ich war in Berlin.</em></p><p class='callout callout--trap'>Le Perfekt ressemble au passé composé : auxiliaire + participe passé, et c'est le passé de l'oral. Mais le parallèle n'est pas exact. Le choix de l'auxiliaire ne se superpose pas : les verbes pronominaux prennent <em>être</em> en français (<em>je me suis lavé</em>) et <b>haben</b> en allemand (<em>Ich habe mich gewaschen</em>), et la liste des verbes avec <em>sein</em> n'est pas celle des verbes avec <em>être</em> : contrôle le verbe. Et l'accord : le participe allemand <b>ne s'accorde pas</b> avec le sujet (<em>Sie ist gegangen</em>, <em>Wir sind gegangen</em>, alors que le français écrit <em>elle est allée, nous sommes allés</em>).</p>"
  },
  "ref:g-praeteritum": {
    title: "Le Präteritum",
    sub: "war, hatte, konnte, wollte : le passé de sein, haben et des modaux",
    body: "<p>En plus du Perfekt, l'allemand a un second passé, le <b>Präteritum</b>. À ce niveau, il sert surtout pour <em>sein</em>, <em>haben</em> et les <b>verbes modaux</b> : à l'oral, on préfère ces formes simples au Perfekt.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sein</th><th>haben</th><th>können</th><th>wollen</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>war</td><td class='it'>hatte</td><td class='it'>konnte</td><td class='it'>wollte</td></tr><tr><td class='it'>du</td><td class='it'>warst</td><td class='it'>hattest</td><td class='it'>konntest</td><td class='it'>wolltest</td></tr><tr><td class='it'>er/sie/es</td><td class='it'>war</td><td class='it'>hatte</td><td class='it'>konnte</td><td class='it'>wollte</td></tr><tr><td class='it'>wir</td><td class='it'>waren</td><td class='it'>hatten</td><td class='it'>konnten</td><td class='it'>wollten</td></tr><tr><td class='it'>ihr</td><td class='it'>wart</td><td class='it'>hattet</td><td class='it'>konntet</td><td class='it'>wolltet</td></tr><tr><td class='it'>sie/Sie</td><td class='it'>waren</td><td class='it'>hatten</td><td class='it'>konnten</td><td class='it'>wollten</td></tr></tbody></table></div><p>Les autres modaux suivent le même schéma, avec une seule règle à retenir : au Präteritum, <em>können, müssen, dürfen, mögen</em> perdent l'Umlaut (<em>konnte, musste, durfte, mochte</em>), alors que <em>wollen</em> et <em>sollen</em> n'en avaient pas (<em>wollte, sollte</em>). À la 1re et à la 3e personne du singulier, la forme est la même : <em>ich war, er war</em>.</p><p>Exemples : <em>Gestern war ich müde. Wir hatten keine Zeit. Ich konnte nicht kommen. Sie wollte nach Hause gehen.</em></p><p>Pour beaucoup d'autres verbes, on préfère à l'oral le <b>Perfekt</b> (<em>Ich habe gearbeitet</em>) ; quelques verbes fréquents (<em>wusste, dachte, gab</em>) apparaissent couramment aussi au Präteritum. Le Präteritum des autres verbes (<em>ging, kam, sagte</em>) se rencontre surtout dans les textes narratifs écrits, comme les récits et les journaux : à ce niveau, il suffit de le reconnaître. La formation du Präteritum des verbes faibles et forts et son emploi à l'écrit sont dans la partie B1 ci-dessous.</p><p class='callout callout--trap'>Le français distingue l'<b>imparfait</b> (<em>j'étais fatigué</em>), le <b>passé composé</b> (<em>j'ai été</em>) et, à l'écrit, le <b>passé simple</b> (<em>je fus</em>) ; le Präteritum ne fait pas ces distinctions : <em>Ich war müde</em> peut rendre <em>j'étais fatigué</em> comme <em>je fus fatigué</em>, selon le contexte. Le français parlé dit volontiers <em>j'ai été à Berlin</em> et <em>je n'ai pas pu venir</em> ; l'allemand parlé dit plus souvent <em>Ich war in Berlin</em> que <em>Ich bin in Berlin gewesen</em>, et <em>Ich konnte nicht</em> que <em>Ich habe nicht gekonnt</em>. Pour la plupart des autres verbes, en revanche, le Perfekt ressemble au passé composé (<em>j'ai mangé, Ich habe gegessen</em>) et c'est lui que l'on emploie à l'oral.</p><h4>B1 : le Präteritum dans les textes écrits</h4><p>Dans les <b>textes écrits</b> (romans, contes, journaux, rapports), le Präteritum est le passé principal du récit ; dans la conversation le Perfekt domine souvent, mais <em>sein</em>, <em>haben</em>, les modaux et quelques autres verbes fréquents s'emploient couramment au Präteritum. Les verbes <b>faibles</b> ajoutent <b>-te</b> au radical (<em>machte, sagte, lernte</em> ; si le radical se termine par <em>-t</em> ou <em>-d</em>, <em>-ete</em> : <em>arbeitete, antwortete</em>). Les verbes <b>forts</b> changent la voyelle du radical (<em>ging, kam, sah</em>) et <b>n'ont pas de terminaison à la 1re et à la 3e personne du singulier</b>. Les verbes <b>mixtes</b> (<em>dachte, brachte</em>) changent de radical et prennent les terminaisons faibles (<em>-te</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitif</th><th>Präteritum (ich/er)</th><th>participe II</th></tr></thead><tbody><tr><td class='it'>machen</td><td class='it'>machte</td><td class='it'>gemacht</td></tr><tr><td class='it'>arbeiten</td><td class='it'>arbeitete</td><td class='it'>gearbeitet</td></tr><tr><td class='it'>gehen</td><td class='it'>ging</td><td class='it'>gegangen</td></tr><tr><td class='it'>kommen</td><td class='it'>kam</td><td class='it'>gekommen</td></tr><tr><td class='it'>sehen</td><td class='it'>sah</td><td class='it'>gesehen</td></tr><tr><td class='it'>geben</td><td class='it'>gab</td><td class='it'>gegeben</td></tr><tr><td class='it'>schreiben</td><td class='it'>schrieb</td><td class='it'>geschrieben</td></tr><tr><td class='it'>finden</td><td class='it'>fand</td><td class='it'>gefunden</td></tr><tr><td class='it'>denken</td><td class='it'>dachte</td><td class='it'>gedacht</td></tr><tr><td class='it'>bringen</td><td class='it'>brachte</td><td class='it'>gebracht</td></tr></tbody></table></div><p>Les personnes : <em>ich ging, du gingst, er ging, wir gingen, ihr gingt, sie gingen</em>. Avec un verbe séparable, la particule va à la fin de la principale (<em>Er stand um sieben auf</em>) et reste attachée dans la subordonnée (<em>..., weil er um sieben aufstand</em>).</p><p>Un texte narratif alterne le Präteritum, pour l'histoire, et le Plusquamperfekt, pour ce qui s'est passé avant (<em>Sie öffnete die Tür. Niemand hatte sie gerufen.</em>).</p><p class='callout callout--trap'>Les formes des verbes forts ne se déduisent pas du français (<em>il alla, il vint</em>) : elles s'apprennent avec l'infinitif et le participe, comme dans le tableau. Le Präteritum allemand ne distingue pas l'imparfait et le passé simple : <em>Er ging nach Hause</em> peut être <em>il allait</em> ou <em>il alla</em>.</p><h4>B2 : le Präteritum dans le récit</h4><p>Dans les récits, les contes, les biographies et les articles de presse, le temps du passé est le <b>Präteritum</b>, y compris pour les verbes forts. Le Perfekt reste dans les paroles des personnages et à l'oral ; le Plusquamperfekt marque ce qui s'était passé avant.</p><p><em>Es war schon spät. Anna saß am Fenster und las. Plötzlich klingelte das Telefon. Sie stand auf, nahm den Hörer ab und erschrak: Ihr Bruder hatte einen Unfall gehabt.</em></p><p>Quelques verbes forts fréquents dans le récit :</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitif</th><th>Präteritum</th><th>infinitif</th><th>Präteritum</th></tr></thead><tbody><tr><td class='it'>fallen</td><td class='it'>fiel</td><td class='it'>laufen</td><td class='it'>lief</td></tr><tr><td class='it'>rufen</td><td class='it'>rief</td><td class='it'>schreien</td><td class='it'>schrie</td></tr><tr><td class='it'>sitzen</td><td class='it'>saß</td><td class='it'>liegen</td><td class='it'>lag</td></tr><tr><td class='it'>stehen</td><td class='it'>stand</td><td class='it'>ziehen</td><td class='it'>zog</td></tr><tr><td class='it'>verlieren</td><td class='it'>verlor</td><td class='it'>beginnen</td><td class='it'>begann</td></tr><tr><td class='it'>bitten</td><td class='it'>bat</td><td class='it'>treffen</td><td class='it'>traf</td></tr><tr><td class='it'>erschrecken</td><td class='it'>erschrak</td><td class='it'>sterben</td><td class='it'>starb</td></tr></tbody></table></div><p class='callout callout--trap'>Le français écrit distingue le passé simple (<em>elle se leva</em>) de l'imparfait (<em>elle était assise</em>) ; l'allemand n'a qu'un Präteritum : <em>Sie saß am Fenster</em> (elle était assise) et <em>Plötzlich stand sie auf</em> (soudain, elle se leva). Ce sont le contexte et les adverbes (<em>plötzlich, immer, jeden Tag</em>) qui font la différence. Le Präteritum n'a donc pas le caractère littéraire du passé simple : c'est le temps normal du récit écrit.</p>"
  },
  "ref:g-plusquamperfekt": {
    title: "Le Plusquamperfekt",
    sub: "hatte gemacht, war gegangen : le passé avant le passé",
    body: "<p>Le <b>Plusquamperfekt</b> se forme comme le Perfekt, mais avec l'auxiliaire au <b>Präteritum</b> : <em>hatte</em> ou <em>war</em> + participe II. L'auxiliaire est le même qu'au Perfekt (<em>haben</em> ou <em>sein</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>haben</th><th>sein</th></tr></thead><tbody><tr><td>ich</td><td class='it'>hatte gemacht</td><td class='it'>war gegangen</td></tr><tr><td>du</td><td class='it'>hattest gemacht</td><td class='it'>warst gegangen</td></tr><tr><td>er/sie/es</td><td class='it'>hatte gemacht</td><td class='it'>war gegangen</td></tr><tr><td>wir</td><td class='it'>hatten gemacht</td><td class='it'>waren gegangen</td></tr><tr><td>ihr</td><td class='it'>hattet gemacht</td><td class='it'>wart gegangen</td></tr><tr><td>sie/Sie</td><td class='it'>hatten gemacht</td><td class='it'>waren gegangen</td></tr></tbody></table></div><p>On l'emploie pour un fait qui s'est passé <b>avant</b> un autre fait passé : <em>Als ich ankam, war der Zug schon abgefahren. Ich habe ihn nicht erkannt, weil er sich verändert hatte.</em> Le verbe de l'action la plus récente est au Präteritum ou au Perfekt. Dans les textes écrits, le couple est Präteritum + Plusquamperfekt ; à l'oral, Perfekt + Plusquamperfekt.</p><p>Avec <b>nachdem</b> (après que), la subordonnée est au Plusquamperfekt : <em>Nachdem ich gegessen hatte, bin ich spazieren gegangen.</em> Si le verbe principal est au présent, la subordonnée est au Perfekt (voir la partie B1 de la fiche sur <em>als</em> et <em>wenn</em>).</p><p class='callout callout--trap'>La forme est très proche du <em>plus-que-parfait</em> français (<em>j'avais mangé, j'étais parti</em>), mais l'auxiliaire n'est pas toujours le même qu'en français : <em>j'avais été</em> se dit <em>ich war gewesen</em>, avec <em>sein</em>, et non avec <em>haben</em>. La construction avec <em>après</em> diffère aussi : le français a souvent l'infinitif passé (<em>Après avoir mangé, je suis sorti</em>), qui n'existe pas avec <em>nachdem</em>. Il faut une subordonnée avec son propre sujet : <em>Nachdem ich gegessen hatte, ...</em>, ou un nom : <em>Nach dem Essen ...</em>.</p>"
  },
  "ref:g-reflexivverben": {
    title: "Les verbes pronominaux",
    sub: "sich waschen, sich freuen : mich/mir, dich/dir, sich",
    body: "<p>Dans les verbes réfléchis, l'action retombe sur le sujet : <em>Ich wasche mich</em> (je me lave). Le pronom réfléchi a deux formes, <b>accusatif</b> et <b>datif</b>, qui ne diffèrent qu'à la 1re et à la 2e personne du singulier.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>accusatif</th><th>datif</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>mich</td><td class='it'>mir</td></tr><tr><td class='it'>du</td><td class='it'>dich</td><td class='it'>dir</td></tr><tr><td class='it'>er/sie/es</td><td class='it'>sich</td><td class='it'>sich</td></tr><tr><td class='it'>wir</td><td class='it'>uns</td><td class='it'>uns</td></tr><tr><td class='it'>ihr</td><td class='it'>euch</td><td class='it'>euch</td></tr><tr><td class='it'>sie/Sie</td><td class='it'>sich</td><td class='it'>sich</td></tr></tbody></table></div><p>En général il faut l'<b>accusatif</b> : <em>Ich wasche mich. Er duscht sich. Wir freuen uns. Ich interessiere mich für Musik.</em> Avec certains verbes, notamment pour les soins du corps, le pronom réfléchi est au <b>datif</b> lorsqu'un autre complément désigne ce qu'on lave, met, etc. : <em>Ich wasche mir die Hände. Du putzt dir die Zähne. Sie zieht sich einen Pullover an.</em> Le cas s'apprend avec la construction du verbe.</p><p>Le pronom se place après le verbe conjugué : <em>Ich treffe mich morgen mit Anna. Der Zug verspätet sich.</em> Si le sujet vient après le verbe, le réfléchi suit un sujet pronom (<em>Heute freue ich mich</em>), mais il peut précéder un sujet nom : <em>Heute freut sich Anna auf den Urlaub.</em> Au Perfekt, l'auxiliaire est <em>haben</em> : <em>Ich habe mich gewaschen.</em></p><p>Verbes utiles : <em>sich waschen, sich duschen, sich anziehen, sich setzen</em>, <em>sich treffen mit</em> + datif, <em>sich freuen auf</em> + accusatif (attendre avec impatience : <em>Ich freue mich auf den Urlaub</em>), <em>sich freuen über</em> + accusatif (être content de quelque chose de présent ou de passé : <em>Ich freue mich über das Geschenk</em>), <em>sich erinnern an</em> + accusatif, <em>sich interessieren für</em> + accusatif, <em>sich ärgern über</em> + accusatif. La préposition et son cas s'apprennent avec le verbe.</p><p class='callout callout--trap'>Le français a lui aussi des verbes pronominaux, et beaucoup coïncident (<em>se laver, se doucher, s'habiller, s'asseoir</em>), mais pas tous : <em>se lever, se réveiller, s'endormir</em> ne sont <b>pas</b> réfléchis en allemand (<em>aufstehen, aufwachen, einschlafen</em>), alors que <em>sich verspäten</em> (être en retard) ou <em>sich bewerben</em> (poser sa candidature) le sont sans l'être en français. Pour les parties du corps, le français emploie le pronom avec l'article (<em>je me lave les mains</em>) et l'allemand fait de même, avec le datif : <em>Ich wasche mir die Hände</em> est la construction habituelle (<em>Ich wasche meine Hände</em> est correct, mais moins naturel). Trois pièges : au passé composé, le français prend <em>être</em> (<em>je me suis lavé</em>) mais l'allemand prend <em>haben</em> (<em>Ich habe mich gewaschen</em>) ; le participe allemand ne s'accorde jamais (<em>je me suis lavée</em>, mais <em>Ich habe mich gewaschen</em>) ; et les prépositions ne se superposent pas : <em>s'intéresser à</em> se dit <em>sich interessieren für</em>, <em>se souvenir de</em> se dit <em>sich erinnern an</em>.</p>"
  },
  "ref:g-verben-dativ": {
    title: "Les verbes avec le datif",
    sub: "helfen, danken, gefallen, gehören, gratulieren : l'objet est au datif",
    body: "<p>Certains verbes ne régissent qu'un seul objet, et cet objet est au <b>datif</b> et non à l'accusatif. Il faut les apprendre avec le verbe.</p><div class='table-wrap'><table class='gt'><thead><tr><th>verbe</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>helfen</td><td class='it'>Ich helfe meinem Bruder.</td></tr><tr><td class='it'>danken</td><td class='it'>Wir danken Ihnen für die Einladung.</td></tr><tr><td class='it'>gratulieren</td><td class='it'>Ich gratuliere dir zum Geburtstag.</td></tr><tr><td class='it'>antworten</td><td class='it'>Er antwortet mir nicht.</td></tr><tr><td class='it'>gefallen</td><td class='it'>Das Hemd gefällt mir.</td></tr><tr><td class='it'>gehören</td><td class='it'>Das Auto gehört meiner Mutter.</td></tr><tr><td class='it'>schmecken</td><td class='it'>Die Pizza schmeckt uns.</td></tr><tr><td class='it'>passen</td><td class='it'>Die Schuhe passen ihm.</td></tr><tr><td class='it'>fehlen</td><td class='it'>Du fehlst mir.</td></tr></tbody></table></div><p>Certains de ces verbes ont la construction de <em>plaire</em> : la chose qui plaît est le <b>sujet</b> (nominatif) et la personne est au datif, et le verbe s'accorde avec la chose : <em>Das Buch gefällt mir. Die Schuhe gefallen mir.</em> Il en va de même pour <em>schmecken, passen, fehlen</em>. Pour dire un goût personnel avec un objet direct, il y a aussi <em>mögen</em> (<em>Ich mag das Buch</em>). Au Perfekt, ces verbes prennent <em>haben</em> : <em>Ich habe ihm geholfen.</em></p><p class='callout callout--trap'>Le français dit <em>je l'aide, je le remercie, je le félicite</em> avec le pronom direct, alors que l'allemand emploie le datif : <em>Ich helfe <b>ihm</b></em>, pas <s>Ich helfe ihn</s> ; <em>Ich danke <b>dir</b></em>. Mais pour d'autres verbes, le français est déjà indirect et le datif allemand correspond : <em>je lui réponds</em> (<em>Ich antworte ihm</em>), <em>ça me plaît</em> (<em>Das gefällt mir</em>), <em>ça lui appartient</em> (<em>Das gehört ihm</em>), et même le renversement de <em>tu me manques</em> (<em>Du fehlst mir</em>, où la personne qui manque est le sujet). Le datif se voit surtout dans les pronoms (<em>mir, dir, ihm</em>) et dans l'article du masculin et du neutre (<em>dem, einem</em>) : si tu lis <em>Ich helfe der Frau</em>, le datif est dans le féminin <em>der</em>. Mieux vaut apprendre le verbe avec un exemple qu'avec la seule traduction.</p>"
  },
  "ref:g-futur": {
    title: "Le futur",
    sub: "Präsens avec un indicateur de temps, ou werden + infinitif",
    body: "<p>Pour parler du futur, l'allemand emploie d'ordinaire le <b>présent</b>, avec un indicateur de temps : <em>Morgen fahre ich nach Wien. Nächste Woche habe ich Urlaub. Bald ziehen wir um.</em></p><p>Il existe aussi le <b>Futur I</b>, formé de <em>werden</em> conjugué en deuxième position et de l'<b>infinitif à la fin</b> de la phrase.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>werden</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>werde</td></tr><tr><td class='it'>du</td><td class='it'>wirst</td></tr><tr><td class='it'>er/sie/es</td><td class='it'>wird</td></tr><tr><td class='it'>wir</td><td class='it'>werden</td></tr><tr><td class='it'>ihr</td><td class='it'>werdet</td></tr><tr><td class='it'>sie/Sie</td><td class='it'>werden</td></tr></tbody></table></div><p><em>Ich werde dich morgen anrufen. Es wird heute Abend regnen. Wir werden im Sommer nach Spanien fahren.</em> On emploie le Futur I quand on veut souligner une promesse, une décision, une prévision, ou quand aucun indicateur de temps ne rend le futur clair : <em>Ich werde es nie vergessen.</em></p><p class='callout callout--trap'>Le français parlé emploie beaucoup le futur proche (<em>je vais t'appeler</em>) et, à l'écrit, le futur simple (<em>j'irai, je mangerai</em>). L'allemand parlé préfère le présent : <em>Morgen gehe ich ins Kino</em> est la forme normale, <em>Morgen werde ich ins Kino gehen</em> est correct mais moins fréquent. Il n'existe pas de construction avec <em>gehen</em> sur le modèle de <em>aller</em> + infinitif : <em>je vais t'appeler</em> se dit <em>Ich rufe dich an</em> ou <em>Ich werde dich anrufen</em>. Après <em>quand</em>, le français met le futur (<em>quand j'aurai le temps</em>), alors que l'allemand reste au présent : <em>Wenn ich Zeit habe, rufe ich dich an.</em> Enfin, <em>werden</em> est aussi un verbe plein : <em>Er wird Arzt</em> (il devient médecin), <em>Es wird kalt</em> (il commence à faire froid) : sans infinitif à la fin, ce n'est pas un futur. L'emploi du futur pour faire des suppositions (<em>il sera chez lui</em>) vient aux niveaux suivants.</p><h4>C1 : le futur de supposition</h4><p>Avec <b>wohl</b>, <b>sicher</b> ou <b>vermutlich</b>, le Futur I exprime une supposition sur le présent ; le <b>Futur II</b> (<em>werden</em> + participe passé + <em>haben</em> ou <em>sein</em>) une supposition sur le passé, ou une action qui sera terminée avant un moment futur.</p><div class='table-wrap'><table class='gt'><thead><tr><th>exemple</th><th>valeur</th></tr></thead><tbody><tr><td class='it'>Er wird wohl müde sein.</td><td>supposition sur le présent</td></tr><tr><td class='it'>Sie wird den Zug wohl verpasst haben.</td><td>supposition sur le passé</td></tr><tr><td class='it'>Bis Montag werde ich den Bericht geschrieben haben.</td><td>terminée avant un moment futur</td></tr></tbody></table></div><p class='callout callout--trap'>Le français connaît surtout ce sens avec le futur antérieur (<em>elle aura raté le train</em> = <em>sie wird den Zug wohl verpasst haben</em>) ; pour le présent il dit plutôt <em>il doit être fatigué</em>. En allemand <em>wohl</em>, <em>sicher</em> ou <em>vermutlich</em> rendent la supposition explicite ; sans adverbe c'est le contexte qui décide, et <em>Er wird müde sein</em> peut aussi être une prévision.</p>"
  },
  "ref:g-praep-verben": {
    title: "Les verbes à préposition fixe",
    sub: "warten auf, denken an, sich freuen über : la préposition fait partie du verbe",
    body: "<p>Beaucoup de verbes veulent une <b>préposition fixe</b> et un <b>cas fixe</b>. Apprends le verbe avec sa préposition et son cas, comme tu le fais pour l'article et le nom.</p><div class='table-wrap'><table class='gt'><thead><tr><th>verbe + préposition</th><th>cas</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>warten auf</td><td>accusatif</td><td class='it'>Ich warte auf den Bus.</td></tr><tr><td class='it'>denken an</td><td>accusatif</td><td class='it'>Ich denke oft an meine Familie.</td></tr><tr><td class='it'>sich freuen auf (futur)</td><td>accusatif</td><td class='it'>Ich freue mich auf den Urlaub.</td></tr><tr><td class='it'>sich freuen über (présent, passé)</td><td>accusatif</td><td class='it'>Ich freue mich über das Geschenk.</td></tr><tr><td class='it'>sich ärgern über</td><td>accusatif</td><td class='it'>Er ärgert sich über den Lärm.</td></tr><tr><td class='it'>sich interessieren für</td><td>accusatif</td><td class='it'>Sie interessiert sich für Musik.</td></tr><tr><td class='it'>sich kümmern um</td><td>accusatif</td><td class='it'>Wir kümmern uns um die Kinder.</td></tr><tr><td class='it'>bitten um</td><td>accusatif</td><td class='it'>Ich bitte um Hilfe.</td></tr><tr><td class='it'>träumen von</td><td>datif</td><td class='it'>Er träumt von einem Haus am Meer.</td></tr><tr><td class='it'>Angst haben vor</td><td>datif</td><td class='it'>Sie hat Angst vor dem Test.</td></tr><tr><td class='it'>teilnehmen an</td><td>datif</td><td class='it'>Wir nehmen an dem Kurs teil.</td></tr><tr><td class='it'>abhängen von</td><td>datif</td><td class='it'>Das hängt vom Wetter ab.</td></tr></tbody></table></div><p>La préposition <em>an</em> se construit avec l'accusatif après <em>denken</em> et avec le datif après <em>teilnehmen</em> : le cas ne se déduit pas du sens, il s'apprend avec le verbe.</p><h4>darauf, worauf : la préposition sans nom</h4><p>Pour une <b>chose</b> ou une situation déjà connue, la préposition s'unit à <b>da-</b> (devant une voyelle, <b>dar-</b>) : <em>Ich warte darauf. Ich freue mich darauf. Er denkt daran. Wir sprechen davon.</em> Pour poser la question, on emploie <b>wo-</b> (<b>wor-</b> devant une voyelle) : <em>Worauf wartest du? Woran denkst du? Wofür interessierst du dich?</em></p><p>Pour une <b>personne</b>, on emploie au contraire la préposition avec le pronom ou avec <em>wen, wem</em> : <em>Ich warte auf ihn. Auf wen wartest du? Mit wem sprichst du?</em></p><p><b>darauf</b> annonce aussi une subordonnée ou un infinitif : <em>Ich freue mich darauf, dass du kommst. Ich warte darauf, dich zu sehen.</em></p><p class='callout callout--trap'>Ne traduis pas la préposition du français : elle est souvent différente. <em>attendre quelqu'un</em> n'a pas de préposition en français, mais <em>warten auf</em> en a une ; <em>penser à</em> se dit <em>denken an</em> ; <em>s'intéresser à</em> se dit <em>sich interessieren für</em> ; <em>avoir peur de</em> se dit <em>Angst haben vor</em> ; <em>dépendre de</em> se dit <em>abhängen von</em>. Parfois les deux langues coïncident (<em>rêver de</em> se dit <em>träumen von</em>), mais on ne peut pas s'y fier.</p><p class='callout callout--trap'><em>darauf, daran, davon</em> font le travail de <em>y</em> et <em>en</em> dans beaucoup de phrases (<em>j'y pense</em> se dit <em>Ich denke daran</em>, <em>j'en parle</em> se dit <em>Ich spreche davon</em>), mais seulement quand on parle de choses. Pour une personne, cette forme n'existe pas : <em>Ich denke an ihn</em>.</p>"
  },
  "ref:g-konjunktiv2": {
    title: "Le Konjunktiv II de politesse",
    sub: "Könnten Sie mir helfen ? Ich hätte gern ... : demandes et conseils",
    body: "<p>Le <b>Konjunktiv II</b> sert à rendre une phrase plus polie ou moins directe. À ce niveau, quelques formes de verbes très fréquents suffisent.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sein</th><th>haben</th><th>können</th><th>werden</th></tr></thead><tbody><tr><td class='it'>ich</td><td class='it'>wäre</td><td class='it'>hätte</td><td class='it'>könnte</td><td class='it'>würde</td></tr><tr><td class='it'>du</td><td class='it'>wärst</td><td class='it'>hättest</td><td class='it'>könntest</td><td class='it'>würdest</td></tr><tr><td class='it'>er/sie/es</td><td class='it'>wäre</td><td class='it'>hätte</td><td class='it'>könnte</td><td class='it'>würde</td></tr><tr><td class='it'>wir</td><td class='it'>wären</td><td class='it'>hätten</td><td class='it'>könnten</td><td class='it'>würden</td></tr><tr><td class='it'>ihr</td><td class='it'>wärt</td><td class='it'>hättet</td><td class='it'>könntet</td><td class='it'>würdet</td></tr><tr><td class='it'>sie/Sie</td><td class='it'>wären</td><td class='it'>hätten</td><td class='it'>könnten</td><td class='it'>würden</td></tr></tbody></table></div><h4>Demandes, souhaits, conseils</h4><ul><li><b>Demande polie</b> : <em>Könnten Sie mir bitte helfen? Würden Sie das Fenster öffnen? Hätten Sie einen Moment Zeit?</em></li><li><b>Souhait</b> : <em>Ich hätte gern einen Kaffee. Ich möchte ein Zimmer.</em> <em>möchte</em> est lui aussi un Konjunktiv II (de <em>mögen</em>) : c'est la forme polie de <em>ich will</em>.</li><li><b>Conseil</b> : <em>Du solltest mehr schlafen. Ich würde zum Arzt gehen.</em></li></ul><p>Avec la plupart des verbes, le Konjunktiv II se forme avec <b>würde + infinitif à la fin</b> (<em>Ich würde gern nach Wien fahren</em>), et les formes propres (<em>wäre, hätte, könnte</em>) servent pour les verbes fréquents. Pour <em>sollen</em> et <em>wollen</em>, la forme coïncide avec le Präteritum (<em>du solltest</em>), et le contexte montre qu'il s'agit d'une recommandation. L'hypothèse irréelle (<em>Wenn ich Zeit hätte, ...</em>) est dans la partie B1 ci-dessous ; le passé (<em>Wenn ich Zeit gehabt hätte, ...</em>) vient aux niveaux suivants.</p><p class='callout callout--trap'>Le français emploie le <b>conditionnel</b> de politesse (<em>je voudrais, pourriez-vous, il faudrait</em>), et l'usage est très proche : <em>Je voudrais un café</em> se dit <em>Ich möchte einen Kaffee</em>, <em>Pourriez-vous m'aider ?</em> se dit <em>Könnten Sie mir helfen?</em> Mais les formes ne se construisent pas pareil : le conditionnel français prend le radical du futur (<em>j'aiderais</em>), le Konjunktiv II allemand part du Präteritum (<em>wäre, hätte, könnte</em>) et, avec la plupart des verbes, passe par <em>würde</em> + infinitif : <em>j'aiderais</em> se dit <em>ich würde helfen</em>. Pour <em>sein, haben</em> et les modaux, on préfère la forme propre : <em>ich könnte</em> est en général préférable (<em>ich würde können</em> est possible, mais moins courant, surtout dans les demandes polies). Une demande sans Konjunktiv II peut paraître brusque : <em>Können Sie mir helfen?</em> passe déjà, mais <em>Könnten Sie mir helfen?</em> est plus doux, et <em>Ich will einen Kaffee</em> sonne sec.</p><h4>B1 : le Konjunktiv II complet au présent</h4><p>Chaque verbe a une forme propre de Konjunktiv II. Dans l'usage courant, on l'entend surtout avec <em>sein, haben</em>, les verbes modaux et quelques verbes fréquents. Pour les <b>verbes forts</b> et certains verbes fréquents, la forme se tire du <b>Präteritum</b> : même radical, souvent avec <b>Umlaut</b> sur <em>a, o, u</em>, terminaisons <em>-e, -est, -e, -en, -et, -en</em> (<em>war → wäre, kam → käme, ging → ginge</em>). Chez les <b>verbes faibles</b>, la forme est identique au Präteritum, sans Umlaut (<em>machte, spielte</em>). Certains verbes mixtes ont des formes propres à apprendre une par une (<em>wusste → wüsste, brachte → brächte, dachte → dächte</em>). Avec les <b>verbes modaux</b>, l'Umlaut apparaît chez ceux qui l'ont déjà à l'infinitif :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>können</th><th>müssen</th><th>dürfen</th><th>mögen</th><th>sollen</th><th>wollen</th></tr></thead><tbody><tr><td>ich/er</td><td class='it'>könnte</td><td class='it'>müsste</td><td class='it'>dürfte</td><td class='it'>möchte</td><td class='it'>sollte</td><td class='it'>wollte</td></tr><tr><td>du</td><td class='it'>könntest</td><td class='it'>müsstest</td><td class='it'>dürftest</td><td class='it'>möchtest</td><td class='it'>solltest</td><td class='it'>wolltest</td></tr><tr><td>wir/sie</td><td class='it'>könnten</td><td class='it'>müssten</td><td class='it'>dürften</td><td class='it'>möchten</td><td class='it'>sollten</td><td class='it'>wollten</td></tr></tbody></table></div><p>Pour <em>sollen</em> et <em>wollen</em>, la forme est identique au Präteritum (<em>sollte, wollte</em>) et le contexte indique qu'il s'agit du Konjunktiv II. <em>Ich möchte</em> est la forme polie déjà connue.</p><ul><li><b>Hypothèse irréelle</b> : <em>Wenn ich mehr Zeit hätte, würde ich reisen. Wenn ich du wäre, würde ich das nicht tun.</em> (la construction complète est dans la fiche sur la condition avec <em>wenn</em>)</li><li><b>Souhait</b> : <em>Ich wäre gern Pilot. Wenn ich doch mehr Zeit hätte!</em></li><li><b>Conseil</b> : <em>An deiner Stelle würde ich mit ihr sprechen. Du solltest mehr schlafen.</em></li><li><b>Opinion prudente</b> : <em>Ich würde sagen, dass das keine gute Idee ist. Das wäre schön.</em></li></ul><p>Avec la plupart des verbes (surtout les verbes faibles, dont la forme coïnciderait avec le Präteritum), on emploie <b>würde + infinitif</b> ; les formes propres restent pour <em>sein, haben</em>, les modaux et quelques verbes fréquents comme <em>wissen, kommen, gehen, geben</em>. <em>Das würde schön sein</em> et <em>Wenn ich Zeit haben würde</em> sont corrects, mais plus lourds.</p><p class='callout callout--trap'><em>je devrais</em> se traduit par <em>sollte</em> (conseil : <em>Ich sollte mehr schlafen</em>) ou par <em>müsste</em> (nécessité plus forte : <em>Ich müsste dringend zum Arzt</em>). Le français emploie l'<em>imparfait</em> après <em>si</em> et le <em>conditionnel</em> dans la conséquence (<em>Si j'avais le temps, je voyagerais</em>) : l'allemand a le Konjunktiv II dans les deux parties, et peut aussi mettre <em>würde</em> dans la phrase avec <em>wenn</em> (<em>Wenn ich weniger arbeiten würde, hätte ich mehr Zeit</em>).</p><h4>B2 : le Konjunktiv II passé</h4><p>Pour une hypothèse ou un regret portant sur le <b>passé</b>, on emploie <b>hätte</b> ou <b>wäre</b> + participe II. Le choix entre <em>hätte</em> et <em>wäre</em> suit celui du Perfekt : <em>wäre</em> avec les verbes de mouvement, de changement d'état et avec <em>sein</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>Perfekt</th><th>Konjunktiv II passé</th></tr></thead><tbody><tr><td>machen</td><td class='it'>ich habe gemacht</td><td class='it'>ich hätte gemacht</td></tr><tr><td>gehen</td><td class='it'>ich bin gegangen</td><td class='it'>ich wäre gegangen</td></tr><tr><td>sein</td><td class='it'>ich bin gewesen</td><td class='it'>ich wäre gewesen</td></tr><tr><td>wissen</td><td class='it'>ich habe gewusst</td><td class='it'>ich hätte gewusst</td></tr></tbody></table></div><ul><li><b>Regret</b> : <em>Hätte ich das bloß gewusst! Ich wäre gern mitgekommen.</em></li><li><b>Hypothèse irréelle</b> : <em>Wenn du früher gekommen wärst, hättest du ihn gesehen.</em></li><li><b>Reproche</b>, avec un verbe de modalité et le double infinitif : <em>Du hättest mich anrufen können.</em></li></ul><p>La forme <em>ich würde gemacht haben</em> existe, mais elle est rare et lourde : au passé, on emploie <em>hätte</em> ou <em>wäre</em>.</p><h4>B2 : als ob, als wenn</h4><p><b>als ob</b> et <b>als wenn</b> (<em>comme si</em>) introduisent une comparaison irréelle, en général au Konjunktiv II, verbe à la fin. Pour un fait simultané on emploie le présent (<em>Er tut so, als ob er nichts wüsste</em>), pour un fait antérieur le passé (<em>Sie sieht aus, als ob sie nicht geschlafen hätte</em>). Avec <b>als</b> seul, le verbe vient tout de suite après : <em>Er tut so, als wüsste er nichts.</em></p><p class='callout callout--trap'><em>Si j'avais su, je serais venu</em> : le français met le plus-que-parfait de l'indicatif après <em>si</em> et le conditionnel passé dans la principale. L'allemand emploie le Konjunktiv II passé dans les deux parties : <em>Wenn ich es gewusst hätte, wäre ich gekommen.</em> De même, après <em>comme si</em> le français garde l'indicatif (<em>comme s'il ne savait rien</em>) ; l'allemand passe normalement au Konjunktiv II (<em>als ob er nichts wüsste</em>), à l'oral souvent avec <em>würde</em>.</p>"
  },
  "ref:g-konjunktiv1": {
    title: "Le Konjunktiv I et le discours rapporté",
    sub: "Sie sagte, sie sei krank : rapporter avec distance",
    body: "<p>Dans la presse, les procès-verbaux et les rapports, on rapporte les paroles d'autrui au <b>Konjunktiv I</b> : celui qui écrit signale qu'il s'agit de la version de cette personne, pas d'un fait qu'il garantit. Il se forme sur le radical de l'infinitif avec les terminaisons <em>-e, -est, -e, -en, -et, -en</em>, et s'emploie surtout à la <b>troisième personne du singulier</b>, où il se distingue de l'indicatif. <em>sein</em> est irrégulier : <em>ich sei, du seist, er sei, wir seien, ihr seiet, sie seien</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>infinitif</th><th>indicatif</th><th>Konjunktiv I</th></tr></thead><tbody><tr><td>sein</td><td class='it'>er ist</td><td class='it'>er sei</td></tr><tr><td>haben</td><td class='it'>er hat</td><td class='it'>er habe</td></tr><tr><td>können</td><td class='it'>er kann</td><td class='it'>er könne</td></tr><tr><td>werden</td><td class='it'>er wird</td><td class='it'>er werde</td></tr><tr><td>wissen</td><td class='it'>er weiß</td><td class='it'>er wisse</td></tr><tr><td>kommen</td><td class='it'>er kommt</td><td class='it'>er komme</td></tr></tbody></table></div><p>Le Konjunktiv I n'a qu'un seul passé, avec <em>habe</em> ou <em>sei</em> + participe (<em>er habe gearbeitet, sie sei gegangen</em>), et un futur avec <em>werde</em> + infinitif (<em>er werde kommen</em>).</p><p>Là où le Konjunktiv I se confond avec l'indicatif (<em>ich habe, wir haben, sie kommen</em>), on emploie le <b>Konjunktiv II</b> : <em>Sie sagten, sie hätten keine Zeit.</em> Si le Konjunktiv II se confond lui aussi avec le Präteritum, on prend <em>würde</em> : <em>Sie sagten, sie würden morgen anrufen.</em> À l'oral, l'indicatif est fréquent : <em>Er hat gesagt, er ist krank.</em></p><h4>Questions, ordres, temps et lieu</h4><ul><li><b>questions</b> : avec <em>ob</em> ou le mot interrogatif, verbe à la fin. <em>Er fragte, ob ich Zeit hätte. Sie fragte, wann der Zug fahre.</em></li><li><b>ordres</b> : avec <em>sollen</em>. <em>Warte!</em> devient <em>Sie sagte, ich solle warten.</em></li><li><b>personne, temps et lieu</b> se déplacent comme en français : <em>ich</em> devient <em>er</em> ou <em>sie</em>, <em>heute</em> devient <em>an diesem Tag</em>, <em>morgen</em> devient <em>am nächsten Tag</em>, <em>gestern</em> devient <em>am Tag davor</em>, <em>hier</em> devient <em>dort</em>. <em>Ich komme morgen.</em> devient <em>Er sagte, er komme am nächsten Tag.</em></li></ul><p>Avec <em>dass</em>, le verbe va à la fin : <em>Sie sagte, dass sie krank sei.</em></p><p class='callout callout--trap'>Au discours indirect, le français applique la concordance des temps (<em>Je suis malade</em> devient <em>elle a dit qu'elle était malade</em> ; <em>Je viendrai</em> devient <em>il a dit qu'il viendrait</em>). L'allemand ne déplace pas le temps : il garde celui du discours direct et change seulement le mode. <em>Ich bin krank</em> devient <em>sie sei krank</em>, <em>Ich war krank</em> devient <em>sie sei krank gewesen</em>, <em>Ich werde kommen</em> devient <em>er werde kommen</em>, et non <s>er wäre gekommen</s>. Le Konjunktiv I ne correspond pas non plus au subjonctif français : au discours rapporté il n'exprime ni doute ni volonté, il signale seulement que les paroles sont celles d'un autre. En dehors du discours rapporté, il apparaît dans des expressions figées (<em>Es lebe ...!, Gott sei Dank!</em>), dans certaines instructions comme les recettes (<em>Man nehme zwei Eier</em>), dans le langage mathématique (<em>Sei x eine natürliche Zahl</em>) et dans des formulations comme <em>Es sei darauf hingewiesen, dass ...</em></p>"
  },
  "ref:g-passiv": {
    title: "Le passif",
    sub: "Das Formular wird ausgefüllt : werden + participe II",
    body: "<p>Dans le passif, l'attention porte sur <b>ce qui se passe</b>, pas sur celui qui le fait. On le forme avec <b>werden</b> conjugué et le <b>participe II</b> à la fin de la phrase :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>Präsens</th><th>Präteritum</th></tr></thead><tbody><tr><td>ich</td><td class='it'>werde gefragt</td><td class='it'>wurde gefragt</td></tr><tr><td>du</td><td class='it'>wirst gefragt</td><td class='it'>wurdest gefragt</td></tr><tr><td>er/sie/es</td><td class='it'>wird gefragt</td><td class='it'>wurde gefragt</td></tr><tr><td>wir</td><td class='it'>werden gefragt</td><td class='it'>wurden gefragt</td></tr><tr><td>ihr</td><td class='it'>werdet gefragt</td><td class='it'>wurdet gefragt</td></tr><tr><td>sie/Sie</td><td class='it'>werden gefragt</td><td class='it'>wurden gefragt</td></tr></tbody></table></div><p>Le complément d'objet de la phrase active (accusatif) devient le <b>sujet</b> (nominatif) de la phrase passive :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>exemple</th></tr></thead><tbody><tr><td>actif</td><td class='it'>Die Beamtin prüft den Antrag.</td></tr><tr><td>passif, présent</td><td class='it'>Der Antrag wird (von der Beamtin) geprüft.</td></tr><tr><td>passif, Präteritum</td><td class='it'>Der Antrag wurde (von der Beamtin) geprüft.</td></tr></tbody></table></div><p>Celui qui fait l'action, s'il faut le dire, s'introduit avec <b>von + datif</b> (<em>von der Beamtin</em>) ; pour une cause ou un moyen, on emploie <b>durch + accusatif</b> (<em>Das Haus wurde durch einen Sturm beschädigt</em>). Très souvent, l'agent n'apparaît pas : <em>Hier wird nicht geraucht. Die Wohnung wurde gestern vermietet.</em></p><p>Dans la proposition principale déclarative, <em>werden</em> est en deuxième position et le participe à la fin ; dans la subordonnée, <em>werden</em> va à la fin, après le participe : <em>..., dass der Antrag geprüft wird.</em> Avec un verbe modal, le passif utilise l'infinitif : <em>Der Antrag muss bis Freitag abgegeben werden.</em></p><p><b>wird geöffnet</b> décrit le processus, c'est-à-dire l'action qui se déroule, maintenant, habituellement ou dans le futur (<em>Die Tür wird um acht geöffnet</em>) ; <b>ist geöffnet</b> décrit l'état qui en résulte (<em>Die Tür ist geöffnet</em>). Ce sont deux passifs différents : le premier, avec <em>werden</em>, est le passif de processus (Vorgangspassiv) et c'est celui de cette fiche ; le second, avec <em>sein</em>, est le passif d'état (Zustandspassiv) et revient au niveau B2.</p><p class='callout callout--trap'>En français, le passif se forme avec <em>être</em> et le participe passé, qui s'accorde avec le sujet (<em>le formulaire est rempli, les formulaires sont remplis</em>). En allemand, l'auxiliaire est <b>werden</b>, pas <em>sein</em>, et le participe ne change jamais. Et <em>est rempli</em> peut dire en français aussi bien le processus que l'état, alors que l'allemand les sépare : <em>Das Formular wird ausgefüllt</em> (quelqu'un le remplit en ce moment) et <em>Das Formular ist ausgefüllt</em> (il est déjà rempli).</p><p class='callout callout--trap'>Le français emploie aussi <em>on</em> (<em>Ici, on parle allemand</em>) et le tour pronominal (<em>Cela se dit souvent</em>). L'allemand a deux solutions : le passif (<em>Hier wird Deutsch gesprochen</em>) ou <em>man</em> avec le verbe à l'actif (<em>Hier spricht man Deutsch</em>). Le passif convient aux textes formels comme les formulaires et les contrats ; <em>man</em>, à l'oral.</p><h4>B2 : le passif au Perfekt, avec les verbes de modalité, et le passif d'état</h4><p>Au <b>Perfekt</b>, le passif se forme avec <b>sein</b> + participe II + <b>worden</b> ; au Plusquamperfekt, avec <em>war</em> + participe + <em>worden</em>. Avec un <b>verbe de modalité</b>, on conjugue le modal et le passif reste à l'infinitif (participe + <em>werden</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>exemple</th></tr></thead><tbody><tr><td>Perfekt</td><td class='it'>Das Haus ist 1900 gebaut worden.</td></tr><tr><td>Plusquamperfekt</td><td class='it'>Die Straße war schon gesperrt worden.</td></tr><tr><td>modal, présent</td><td class='it'>Der Antrag muss bis Freitag geprüft werden.</td></tr><tr><td>modal, Präteritum</td><td class='it'>Das Problem konnte nicht gelöst werden.</td></tr><tr><td>subordonnée</td><td class='it'>..., dass die Brücke renoviert worden ist.</td></tr></tbody></table></div><p>Le <b>passif d'état</b> (Zustandspassiv) se forme avec <b>sein</b> + participe II et décrit le résultat d'une action terminée : <em>Die Tür ist geschlossen. Das Geschäft war gestern geschlossen.</em> Le passif d'action dit ce qui se passe : <em>Die Tür wird um acht geschlossen.</em></p><p class='callout callout--trap'>Le français emploie <em>être</em> pour les deux : <em>la porte est fermée</em> peut décrire un état ou une action habituelle (<em>est fermée à huit heures</em>). L'allemand les sépare : <em>ist geschlossen</em> pour l'état, <em>wird geschlossen</em> pour l'action. <em>A été construite</em> se dit <em>ist gebaut worden</em>, jamais <s>ist gebaut gewesen</s>, et dans le passif le participe de <em>werden</em> est <b>worden</b>, pas <em>geworden</em> (<em>Er ist Arzt geworden</em>).</p><h4>C1 : les alternatives au passif</h4><p>Dans les textes formels, l'allemand exprime aussi une possibilité ou une nécessité sans nommer celui qui agit, avec des formes qui associent l'idée passive à une valeur modale :</p><div class='table-wrap'><table class='gt'><thead><tr><th>forme</th><th>valeur</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>sich lassen + infinitif</td><td>on peut</td><td class='it'>Das lässt sich leicht erklären.</td></tr><tr><td class='it'>sein + zu + infinitif</td><td>on peut ou on doit</td><td class='it'>Der Antrag ist bis Freitag abzugeben. Das ist nicht zu ändern.</td></tr><tr><td class='it'>adjectif en -bar</td><td>qu'on peut</td><td class='it'>Das Wasser ist trinkbar. Die Aufgabe ist lösbar.</td></tr><tr><td class='it'>man + actif</td><td>impersonnel</td><td class='it'>Das macht man so.</td></tr></tbody></table></div><p><em>sein + zu</em> peut signifier « on peut » ou « on doit » : le contexte décide, et dans les règlements c'est en général une obligation (<em>Der Antrag ist abzugeben</em> = <em>muss abgegeben werden</em>). Avec un verbe séparable, <em>zu</em> se place entre la particule et le verbe : <em>abzugeben</em>.</p><p class='callout callout--trap'>Le français a des équivalents proches : <em>se laisser</em> + infinitif existe (<em>cela se laisse expliquer</em>), mais on dit plus souvent <em>cela s'explique facilement</em> ou <em>on peut l'expliquer</em> ; <em>être à</em> + infinitif (<em>le formulaire est à remettre vendredi</em>) correspond bien à <em>ist abzugeben</em> ; et <em>-bar</em> fonctionne comme <em>-able</em> (<em>trinkbar</em> « buvable » ; <em>lösbar</em>, pour un problème, « qu'on peut résoudre »).</p>"
  },
  "ref:g-praep-akk": {
    title: "Les prépositions avec l'accusatif",
    sub: "für, ohne, um, durch, gegen",
    body: "<p>Ces prépositions demandent toujours l'<b>accusatif</b> : par conséquent, seul le masculin change (<em>den, einen, keinen, meinen</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>für</td><td>pour</td><td class='it'>Das Geschenk ist für den Lehrer.</td></tr><tr><td class='it'>ohne</td><td>sans</td><td class='it'>Ich trinke Kaffee ohne Zucker.</td></tr><tr><td class='it'>um</td><td>autour de, pour les heures</td><td class='it'>Wir gehen um die Ecke. Um acht Uhr.</td></tr><tr><td class='it'>durch</td><td>à travers</td><td class='it'>Wir gehen durch den Park.</td></tr><tr><td class='it'>gegen</td><td>contre, vers</td><td class='it'>Ich bin gegen den Plan.</td></tr></tbody></table></div><p>Avec les pronoms : <em>für mich, für dich, für ihn, ohne sie, gegen uns</em>. Une formule utile pour la ville : <em>Gehen wir ins Kino?</em> (<em>ins</em> = <em>in das</em> ; l'emploi de <em>in</em> avec le mouvement se voit plus tard).</p><p class='callout callout--trap'>En français, <em>pour Marc</em> ne change rien au nom ni à l'article. En allemand, le cas est marqué par l'article masculin : <em>für den Mann</em>, <em>für einen Freund</em>, et non <s>für der Mann</s>. Avec <em>ohne</em> devant un nom non comptable, on omet en général l'article, comme en français (<em>ohne Zucker, ohne Milch</em> : <em>sans sucre, sans lait</em>).</p>"
  },
  "ref:g-praep-dativ": {
    title: "Les prépositions avec le datif",
    sub: "mit, zu, bei, aus, von, nach, seit",
    body: "<p>Ces sept prépositions demandent toujours le <b>datif</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>mit</td><td>avec, moyen de transport</td><td class='it'>Ich fahre mit dem Bus.</td></tr><tr><td class='it'>zu</td><td>vers une personne ou un lieu</td><td class='it'>Ich gehe zum Bahnhof. Wir gehen zur Schule.</td></tr><tr><td class='it'>bei</td><td>chez, auprès de</td><td class='it'>Ich wohne bei meiner Tante. Er ist beim Arzt.</td></tr><tr><td class='it'>aus</td><td>de (provenance)</td><td class='it'>Ich komme aus Italien.</td></tr><tr><td class='it'>von</td><td>de (point de départ)</td><td class='it'>Der Brief ist von meiner Mutter.</td></tr><tr><td class='it'>nach</td><td>destination : vers les villes et les pays sans article ; après</td><td class='it'>Ich fahre nach Berlin. Wir fliegen nach Italien. Nach dem Essen.</td></tr><tr><td class='it'>seit</td><td>depuis (durée ou point de départ, situation qui continue)</td><td class='it'>Ich wohne seit einem Jahr hier. Ich lerne seit Januar Deutsch.</td></tr></tbody></table></div><p>Beaucoup de prépositions fusionnent avec l'article : <b>zu dem → zum</b>, <b>zu der → zur</b>, <b>bei dem → beim</b>, <b>von dem → vom</b>. <em>Gehen Sie zum Bahnhof. Er ist beim Friseur. Ich komme vom Bahnhof.</em></p><p class='callout callout--trap'>Comme en français (<em>à + le → au, de + le → du</em>), l'allemand contracte, mais pas au même endroit : <em>zu der</em> donne <em>zur</em>, alors que <em>à la</em> ne se contracte pas. Les équivalents ne se superposent pas non plus : <em>de</em> se dit <em>aus</em> (provenance : <em>Ich komme aus Rom</em>) ou <em>von</em> (point de départ : <em>vom Bahnhof</em>) ; <em>chez</em> se dit <em>bei</em> (au repos : <em>beim Arzt</em>) ou <em>zu</em> (avec mouvement : <em>zum Arzt</em>) ; <em>depuis</em> + durée ou point de départ (<em>seit Montag, seit Januar, seit 2020</em>) se dit <em>seit</em>, pour une situation qui continue. <em>en autobus</em>, pour nommer le moyen de transport, se dit habituellement <b>mit dem Bus</b> ; <em>im Bus</em> (<em>in dem Bus</em>) n'est pas une faute, mais indique le véhicule dans lequel on se trouve. <em>nach</em> indique la destination : <em>aller à Berlin, en Italie</em> se dit <em>nach Berlin, nach Italien</em>, sans article. Pour le lieu où l'on est, l'allemand dit <em>in</em> : <em>J'habite à Berlin</em> est <em>Ich wohne in Berlin</em>, <em>en Italie</em> est <em>in Italien</em>. Avec les pays qui ont un article, on emploie en revanche <em>in</em> + accusatif (<em>in die Schweiz, in die Türkei, in die USA</em>), contraste à connaître, pas à employer pour l'instant. Formules figées : <em>zu Fuß</em> (à pied), <em>nach Hause</em> (vers la maison), <em>zu Hause</em> (à la maison).</p>"
  },
  "ref:g-wechselpraep": {
    title: "Les prépositions avec datif ou accusatif",
    sub: "wo ? avec le datif : in, an, auf, vor, hinter, neben, ...",
    body: "<p>Neuf prépositions peuvent régir le datif ou l'accusatif. Pour l'instant, on ne voit que la réponse à <b>wo ?</b> (où ? position, lieu où l'on est), qui demande le <b>datif</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>in</td><td>dans</td><td class='it'>Ich bin in der Küche. Er wohnt in der Stadt.</td></tr><tr><td class='it'>an</td><td>contre un bord, un mur</td><td class='it'>Das Bild hängt an der Wand. Ich sitze am Fenster.</td></tr><tr><td class='it'>auf</td><td>sur, au contact</td><td class='it'>Das Buch liegt auf dem Tisch.</td></tr><tr><td class='it'>vor</td><td>devant</td><td class='it'>Der Bus hält vor dem Hotel.</td></tr><tr><td class='it'>hinter</td><td>derrière</td><td class='it'>Der Bahnhof ist hinter dem Rathaus.</td></tr><tr><td class='it'>neben</td><td>à côté de</td><td class='it'>Das Café ist neben der Post.</td></tr><tr><td class='it'>über</td><td>au-dessus (sans contact)</td><td class='it'>Die Lampe hängt über dem Tisch.</td></tr><tr><td class='it'>unter</td><td>sous</td><td class='it'>Die Katze schläft unter dem Tisch.</td></tr><tr><td class='it'>zwischen</td><td>entre</td><td class='it'>Das Kino ist zwischen der Bank und dem Park.</td></tr></tbody></table></div><p>Contractions : <b>in dem → im</b>, <b>an dem → am</b> : <em>Ich bin im Park. Wir sind am Bahnhof.</em> Question : <em>Wo ist der Bahnhof? Hinter dem Rathaus.</em></p><p class='callout callout--trap'>Le français emploie des prépositions invariables (<em>dans, sur, sous, devant, derrière, entre</em>) et c'est le verbe qui dit si l'on est immobile ou si l'on va quelque part : <em>je suis dans la cuisine, je vais dans la cuisine</em>. En allemand, c'est le cas qui change le sens : <em>in der Küche</em> (datif) dit où l'on <em>est</em>, tandis que le mouvement vers le lieu (<em>in die Küche</em>, accusatif) se voit dans la partie A2, plus bas. Ici, demande-toi toujours : <em>wo ?</em> alors datif. <em>sur</em> se traduit aussi de deux façons : <em>auf dem Tisch</em> (sur) et <em>an der Wand</em> (accroché au mur).</p><h4>A2 : wohin ? avec l'accusatif</h4><p>Quand la phrase répond à <b>wohin ?</b> (vers où ?), c'est-à-dire quand le lieu est la destination du déplacement, les mêmes prépositions demandent l'<b>accusatif</b> : <em>Ich gehe in die Küche. Er legt das Buch auf den Tisch. Wir fahren ans Meer.</em> Ce qui compte, c'est la destination, pas la simple présence d'un mouvement : un mouvement à l'intérieur d'un lieu garde le datif (<em>Ich gehe im Park spazieren</em>, je me promène dans le parc), alors que <em>Ich gehe in den Park</em> (je vais au parc) prend l'accusatif. Les contractions sont <em>in das → ins, an das → ans, auf das → aufs</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>wo ? (datif)</th><th>wohin ? (accusatif)</th></tr></thead><tbody><tr><td class='it'>Ich bin im Park.</td><td class='it'>Ich gehe in den Park.</td></tr><tr><td class='it'>Das Buch liegt auf dem Tisch.</td><td class='it'>Ich lege das Buch auf den Tisch.</td></tr><tr><td class='it'>Die Flasche steht auf dem Tisch.</td><td class='it'>Ich stelle die Flasche auf den Tisch.</td></tr><tr><td class='it'>Er sitzt am Fenster.</td><td class='it'>Er setzt sich ans Fenster.</td></tr></tbody></table></div><p>L'allemand choisit le verbe selon la position de l'objet : <b>stellen / stehen</b> pour un objet debout, <b>legen / liegen</b> pour un objet couché, <b>setzen / sitzen</b> pour qui s'assoit ou est assis. Les verbes d'action (<em>stellen, legen, setzen</em>) demandent <em>wohin</em> et l'accusatif ; ceux d'état (<em>stehen, liegen, sitzen</em>) demandent <em>wo</em> et le datif. Avec les noms de villes et de pays sans article, on emploie <em>nach</em> (<em>Ich fahre nach Berlin</em>), avec les personnes <em>zu</em> + datif (<em>Ich gehe zu meiner Freundin</em>).</p><p class='callout callout--trap'>Le français emploie un verbe pour presque tout (<em>mettre</em>) et la même préposition pour l'état et le mouvement (<em>sur la table</em>) : <em>je mets le livre sur la table, le livre est sur la table</em>. L'allemand distingue deux fois : avec le <b>verbe</b> (<em>legen / liegen</em>) et avec le <b>cas</b> (accusatif / datif).</p>"
  },
  "ref:g-temporalangaben": {
    title: "Heure, jours, mois et dates",
    sub: "um, am, im ; von ... bis, vor, seit",
    body: "<h4>L'heure</h4><p><em>Wie spät ist es?</em> / <em>Wie viel Uhr ist es?</em> Réponse : <em>Es ist acht Uhr.</em> Pour une heure précise : <em>Um acht Uhr.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>heure</th></tr></thead><tbody><tr><td class='it'>7:00</td><td class='it'>Es ist sieben Uhr.</td></tr><tr><td class='it'>7:15</td><td class='it'>Es ist Viertel nach sieben.</td></tr><tr><td class='it'>7:30</td><td class='it'>Es ist <b>halb acht</b>.</td></tr><tr><td class='it'>7:45</td><td class='it'>Es ist Viertel vor acht.</td></tr><tr><td class='it'>7:10</td><td class='it'>Es ist zehn nach sieben.</td></tr><tr><td class='it'>7:50</td><td class='it'>Es ist zehn vor acht.</td></tr></tbody></table></div><p class='callout callout--trap'><b><em>halb acht</em> veut dire sept heures et demie</b>, pas huit heures et demie : on compte vers l'heure qui vient. Le français dit <em>et demie</em> à partir de l'heure déjà passée : c'est le piège le plus fréquent. En revanche <em>Viertel nach sieben</em> (<em>sept heures et quart</em>) et <em>Viertel vor acht</em> (<em>huit heures moins le quart</em>) se superposent. Comme en français (<em>il est sept heures</em>), on dit <em>es ist</em> au singulier.</p><h4>Prépositions de temps</h4><ul><li><b>um</b> + heure : <em>um acht Uhr</em></li><li><b>am</b> + jour, partie de la journée, date : <em>am Montag, am Abend, am 3. Mai</em> (mais <em>in der Nacht</em>)</li><li><b>im</b> + mois, saison : <em>im Januar, im Sommer</em></li><li><b>von ... bis</b> : <em>von Montag bis Freitag, von acht bis vier</em></li><li><b>vor</b> (il y a) et <b>seit</b> (depuis) + datif : <em>vor einer Woche, seit Montag</em></li></ul><p>Les jours : <em>Montag, Dienstag, Mittwoch, Donnerstag, Freitag, Samstag, Sonntag</em>. Avec <b>-s</b>, on dit que quelque chose arrive chaque fois : <em>montags, morgens, abends</em> (le français : <em>le lundi, le matin, le soir</em>). Les dates se disent avec l'ordinal : <em>am ersten, zweiten, dritten, vierten Mai</em> ; écrites <em>am 1. Mai</em>.</p><p class='callout callout--trap'>Les jours et les mois prennent une <b>majuscule</b> en allemand, pas en français. Pour les dates, le français emploie l'article seul (<em>le 3 mai</em>) et le nombre cardinal (<em>le trois mai</em>) ; l'allemand met <em>am</em> et l'<b>ordinal</b> : <em>am dritten Mai</em>.</p>"
  },
  "ref:g-satz-v2": {
    title: "L'ordre des mots dans la phrase simple",
    sub: "le verbe conjugué en deuxième position",
    body: "<p>Dans une proposition principale déclarative, le <b>verbe conjugué est toujours en deuxième position</b>. La première position peut être n'importe quel élément, et quand ce n'est pas le sujet, le sujet passe après le verbe.</p><ul><li><em>Ich lerne heute Deutsch.</em></li><li><em>Heute lerne ich Deutsch.</em> (inversion)</li><li><em>Montags arbeite ich.</em></li></ul><h4>Questions</h4><ul><li><b>Mot interrogatif</b> en première place, verbe en deuxième : <em>Wo wohnst du? Was isst du? Wann kommst du?</em> L'ordre ressemble à <em>Où habites-tu ?</em>.</li><li><b>Question oui / non</b> : le verbe passe en tête (le verbe en deuxième place vaut pour les déclaratives et les questions à mot interrogatif) : <em>Wohnst du in Berlin? Kommst du heute?</em> Pas d'équivalent de <em>est-ce que</em>.</li></ul><p>En français, l'ordre sujet-verbe est fixe dans la phrase déclarative : <em>Aujourd'hui, j'apprends l'allemand</em>. Le français a l'inversion dans certaines questions (<em>Habites-tu ?</em>), mais pas après un complément de temps. L'allemand, lui, inverse dès que la première place est occupée par autre chose que le sujet.</p><p class='callout callout--trap'>Erreur typique : <em>Heute ich lerne Deutsch.</em> C'est le calque du français. Après <em>heute</em>, le verbe vient avant le sujet : <em>Heute lerne ich Deutsch.</em></p>"
  },
  "ref:g-negation": {
    title: "La négation : nicht et kein",
    sub: "nicht pour le verbe, l'adjectif ; kein pour le nom ; doch",
    body: "<p>Le français encadre le verbe (<em>ne … pas</em>). L'allemand a deux mots simples, selon ce qu'on nie.</p><ul><li><b>kein</b> nie un nom précédé de <em>ein</em> ou sans article. Il s'emploie comme <em>pas de / pas un</em> et se décline comme <em>ein</em> : <em>Ich habe keinen Bruder. Wir haben keine Zeit. Ich trinke keinen Kaffee.</em></li><li><b>nicht</b> nie tout le reste : un verbe, un adjectif, un adverbe, un nom avec l'article défini ou un possessif : <em>Ich arbeite nicht. Das ist nicht gut. Ich kenne den Mann nicht.</em></li></ul><h4>Où placer nicht</h4><ul><li>Dans une phrase simple, <em>nicht</em> se met en général à la <b>fin</b> (tendance, pas règle absolue) : <em>Ich kenne ihn nicht. Er kommt nicht.</em></li><li>Avant un adjectif ou un complément de lieu : <em>Das Buch ist nicht teuer. Ich wohne nicht in Berlin.</em></li></ul><h4>Doch</h4><p>Pour répondre « si » à une question négative, l'allemand a un mot : <em>doch</em>. <em>Du kommst nicht? – Doch!</em> (Si, je viens.) Il ne faut pas répondre <em>ja</em>.</p><p class='callout callout--trap'>Il n'y a pas de <em>ne</em> : <em>Ich nicht arbeite</em> est faux. Et <em>pas de</em> + nom devient <em>kein</em> : <em>Je n'ai pas de frère</em> = <em>Ich habe keinen Bruder</em>.</p>"
  },
  "ref:g-konnektoren": {
    title: "Relier les phrases : und, aber, oder, denn",
    sub: "position zéro : l'ordre ne change pas",
    body: "<p>Ces quatre conjonctions relient deux propositions principales et se placent <b>en position zéro</b> : elles ne comptent pas comme premier élément et chaque proposition garde l'ordre propre à son type : verbe en <b>deuxième position</b> dans une déclarative, en <b>première position</b> dans une question oui/non (<em>Gehen wir ins Kino, oder bleiben wir zu Hause?</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>und</td><td>et</td><td class='it'>Ich gehe ins Kino, und er bleibt zu Hause.</td></tr><tr><td class='it'>aber</td><td>mais</td><td class='it'>Ich bin müde, aber ich gehe ins Kino.</td></tr><tr><td class='it'>oder</td><td>ou</td><td class='it'>Gehen wir ins Kino, oder bleiben wir zu Hause?</td></tr><tr><td class='it'>denn</td><td>car (explique)</td><td class='it'>Ich bleibe zu Hause, denn ich bin müde.</td></tr></tbody></table></div><p>Le sujet reste avant le verbe ; si la deuxième phrase a un autre élément en tête, après la conjonction le verbe garde malgré tout sa position : <em>Ich arbeite, aber am Samstag habe ich frei.</em> Si le sujet est le même, on peut l'omettre après <b>und, oder, aber</b> : <em>Ich gehe ins Kino und sehe einen Film.</em> Pas après <b>denn</b> : le sujet est répété (<em>Ich bleibe zu Hause, denn ich bin müde</em>).</p><p>Avant <b>aber</b> et <b>denn</b>, la virgule est obligatoire ; avant <b>und</b> et <b>oder</b>, elle est facultative entre deux propositions principales.</p><p class='callout callout--trap'><em>parce que</em> se traduit de deux façons. <b>denn</b> est proche de <em>car</em> : il introduit une explication et <b>ne</b> déplace <b>pas</b> le verbe (<em>denn ich bin müde</em>), et il peut ouvrir une nouvelle phrase (<em>Ich bleibe zu Hause. Denn ich bin müde.</em>). <b>weil</b>, l'équivalent de <em>parce que</em>, envoie le verbe à la fin : il a sa propre fiche. Avec <em>denn</em>, le verbe reste à sa place.</p><h4>A2 : deshalb et trotzdem</h4><p><b>deshalb</b> (c'est pourquoi, pour cette raison) et <b>trotzdem</b> (pourtant, malgré tout) relient deux propositions principales, mais se comportent autrement que <em>und, aber, denn</em> : ils occupent la <b>première position</b> de la seconde phrase, donc le <b>verbe vient juste après</b> et le sujet le suit.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>deshalb</td><td>conséquence</td><td class='it'>Es regnet. Deshalb bleibe ich zu Hause.</td></tr><tr><td class='it'>trotzdem</td><td>contraste, malgré tout</td><td class='it'>Ich bin müde. Trotzdem gehe ich ins Kino.</td></tr></tbody></table></div><p>On peut les employer après un point ou après une virgule, et ils peuvent aussi se placer plus loin dans la phrase, hors de la première position : <em>Ich bleibe deshalb zu Hause.</em> Synonymes de <em>deshalb</em> : <em>deswegen, darum</em>.</p><p class='callout callout--trap'>En français, <em>donc, pourtant, quand même</em> ne changent pas l'ordre de la phrase (<em>Il pleut, donc je reste à la maison</em>). L'allemand, avec <em>deshalb</em> et <em>trotzdem</em>, inverse le sujet et le verbe : <em>Deshalb <b>bleibe ich</b></em>, pas <s>Deshalb ich bleibe</s>. Ce ne sont pas des conjonctions de subordination : elles n'envoient pas le verbe à la fin, comme le fait <em>weil</em>.</p><h4>B1 : zwar ... aber, sowohl ... als auch, weder ... noch</h4><p>Certaines conjonctions fonctionnent par paires et relient deux éléments.</p><div class='table-wrap'><table class='gt'><thead><tr><th>paire</th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>zwar ... aber</td><td>certes ... mais</td><td class='it'>Das Hotel ist zwar teuer, aber es liegt zentral.</td></tr><tr><td class='it'>sowohl ... als auch</td><td>aussi bien ... que</td><td class='it'>Sie spricht sowohl Deutsch als auch Englisch.</td></tr><tr><td class='it'>weder ... noch</td><td>ni ... ni</td><td class='it'>Ich habe weder Zeit noch Lust.</td></tr></tbody></table></div><p><b>zwar</b> concède quelque chose, <b>aber</b> introduit le contraste et reste en position zéro (le verbe est en deuxième position après l'élément qui suit). <em>zwar</em> peut aussi se placer au début : <em>Zwar ist das Hotel teuer, aber es liegt zentral.</em> Avec <b>sowohl ... als auch</b> et <b>weder ... noch</b>, les deux éléments peuvent être sujets : <em>Sowohl Anna als auch Tom kommen.</em> Avec <em>weder ... noch</em>, le verbe est déjà négatif : on n'ajoute ni <em>nicht</em> ni <em>kein</em>.</p><p>Pour le contraste avec <em>obwohl</em> et <em>trotzdem</em>, voir la fiche sur la concessive.</p><p class='callout callout--trap'>En français, <em>ni ... ni</em> s'emploie avec <em>ne</em> devant le verbe (<em>Je n'ai ni temps ni envie</em>) ; l'allemand non : <em>Ich habe weder Zeit noch Lust</em>, jamais <s>Ich habe nicht weder Zeit noch Lust</s>. <em>zwar ... aber</em> se rend par <em>certes ... mais</em> ou <em>il est vrai que ... mais</em>, et la paire est beaucoup plus fréquente en allemand.</p><h4>B2 : einerseits ... andererseits, jedoch, allerdings, sondern, vielmehr</h4><ul><li><b>einerseits ... andererseits</b> (<em>d'un côté ... de l'autre</em>) : <em>Einerseits ist die Stadt teuer, andererseits gibt es dort viele Jobs.</em></li><li><b>jedoch</b> (<em>cependant</em>) se place en première position, avec le verbe juste après, ou à l'intérieur de la phrase : <em>Das Angebot ist gut, jedoch ist der Preis hoch. Der Preis ist jedoch hoch.</em></li><li><b>allerdings</b> (<em>toutefois, il est vrai</em>) nuance ce qu'on vient de dire : <em>Das Hotel war schön, allerdings war es etwas laut.</em></li><li><b>sondern</b> corrige après une négation : <em>Er kommt nicht heute, sondern morgen.</em></li><li><b>vielmehr</b> (<em>bien plutôt</em>) renforce la correction : <em>Das ist kein Problem, vielmehr ist es eine Chance.</em></li></ul><p class='callout callout--trap'>Le français <em>mais</em> a deux traductions. On emploie <em>aber</em> quand la seconde partie ajoute une opposition (<em>Er ist müde, aber er arbeitet</em>), <em>sondern</em> quand elle remplace ce qui a été nié (<em>pas moi, mais toi</em> : <em>nicht ich, sondern du</em>). Après <em>nicht</em> ou <em>kein</em> suivis d'une rectification, <em>aber</em> est fautif.</p>"
  },
  "ref:g-wortstellung": {
    title: "L'ordre des mots dans le champ central",
    sub: "datif et accusatif, pronoms et noms ; temps, cause, manière, lieu",
    body: "<p>Entre le verbe conjugué (deuxième position) et le second élément verbal à la fin s'étend le <b>champ central</b> (<em>Mittelfeld</em>). L'ordre de ses éléments suit quelques règles de base, qui donnent la forme neutre de la phrase : pour mettre quelque chose en relief, on peut le déplacer en avant.</p><h4>Objets : datif et accusatif</h4><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>exemple</th></tr></thead><tbody><tr><td>deux noms : le datif d'abord</td><td class='it'>Ich schenke meiner Schwester ein Buch.</td></tr><tr><td>pronom et nom : le pronom d'abord</td><td class='it'>Ich schenke ihr ein Buch. Ich schenke es meiner Schwester.</td></tr><tr><td>deux pronoms : l'accusatif d'abord</td><td class='it'>Ich schenke es ihr.</td></tr></tbody></table></div><p>En bref : les <b>pronoms viennent avant les noms</b> ; entre deux noms, le <b>datif</b> précède l'accusatif ; entre deux pronoms, c'est l'<b>accusatif</b> qui précède le datif.</p><h4>Indications : temps, cause, manière, lieu</h4><p>Les éléments qui disent <em>quand, pourquoi, comment, où</em> suivent d'ordinaire l'ordre <b>te-ka-mo-lo</b> (temporal, kausal, modal, lokal) : <em>Ich fahre morgen wegen der Arbeit mit dem Zug nach Berlin.</em> Il n'en faut pas la totalité : il suffit de garder l'ordre des éléments présents (<em>Ich fahre morgen mit dem Zug nach Berlin</em>).</p><p>Le second élément verbal reste à la fin, donc tout le champ central se trouve entre les deux : <em>Ich habe gestern meiner Schwester ein Buch geschenkt.</em></p><p class='callout callout--trap'>En français, les pronoms se placent devant le verbe (<em>je le lui offre</em>) et les compléments de temps et de lieu se déplacent assez librement. En allemand, les pronoms sont des mots séparés qui viennent <b>après</b> le verbe (<em>Ich schenke es ihr</em>), et le <em>temps</em> précède en général le <em>lieu</em>. Un détail piège : avec deux pronoms de la 3e personne, l'accusatif vient d'abord dans les deux langues (<em>je le lui donne, Ich gebe es ihm</em>), mais avec <em>me, te</em> le français inverse (<em>il me le donne</em>), alors que l'allemand garde l'accusatif en premier (<em>Er gibt es mir</em>). Avec deux noms, le français dit <em>j'offre un livre à ma sœur</em> (l'objet direct d'abord) et l'allemand met le datif d'abord (<em>meiner Schwester ein Buch</em>). Ce n'est pas une règle rigide : elle sert à construire des phrases naturelles et à reconnaître quand l'ordre est marqué.</p>"
  },
  "ref:g-nebensatz-weil": {
    title: "La causale avec weil et da",
    sub: "weil ich müde bin : le verbe conjugué va à la fin",
    body: "<p><b>weil</b> (parce que) et <b>da</b> (puisque, étant donné que) introduisent une proposition <b>subordonnée</b> : le verbe conjugué va <b>à la fin</b>, et il y a toujours une virgule entre la principale et la subordonnée.</p><p><em>Ich bleibe zu Hause, weil ich müde bin. Er kommt nicht, weil er krank ist.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th>situation</th><th>exemple</th></tr></thead><tbody><tr><td>verbe simple</td><td class='it'>weil ich müde bin</td></tr><tr><td>verbe séparable (préfixe rattaché)</td><td class='it'>weil ich früh aufstehe</td></tr><tr><td>verbe modal : le modal à la fin</td><td class='it'>weil ich arbeiten muss</td></tr><tr><td>Perfekt : l'auxiliaire à la fin</td><td class='it'>weil ich viel gearbeitet habe</td></tr></tbody></table></div><p>Si la subordonnée est placée <b>avant</b>, la principale commence par le verbe conjugué, juste après la virgule : <em>Weil ich müde bin, bleibe ich zu Hause.</em> <b>Da</b> fait le même travail, mais on l'emploie d'ordinaire en début de phrase et à l'écrit : <em>Da es regnet, bleiben wir zu Hause.</em> À la question <em>Warum?</em>, on peut répondre par la seule subordonnée : <em>Warum kommst du nicht? Weil ich krank bin.</em></p><p class='callout callout--trap'>Le français a lui aussi deux mots proches : <em>car</em> ressemble à <b>denn</b> (le verbe reste en deuxième position : <em>Ich bleibe zu Hause, denn ich bin müde</em>), <em>parce que</em> correspond à <b>weil</b> (verbe à la fin : <em>..., weil ich müde bin</em>) et <em>puisque</em> à <b>da</b>. Mais l'ordre des mots ne change pas en français après <em>parce que</em> (<em>je reste à la maison parce que je suis fatigué</em>) : en allemand, après <em>weil</em> ou <em>da</em>, le verbe conjugué part à la fin. À la question directe, on dit <em>warum</em>, jamais <s>weil</s>.</p>"
  },
  "ref:g-nebensatz-temporal": {
    title: "Quand : als et wenn",
    sub: "als pour un fait passé unique, wenn pour les faits répétés et le présent",
    body: "<p>Le français a un seul <em>quand</em> ; l'allemand en a trois, selon la situation. <b>als</b> et <b>wenn</b> introduisent des subordonnées temporelles : le verbe conjugué va <b>à la fin</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>situation</th><th>mot</th><th>exemple</th></tr></thead><tbody><tr><td>un fait unique dans le passé</td><td class='it'>als</td><td class='it'>Als ich ankam, hat es geregnet.</td></tr><tr><td>un fait répété, même dans le passé</td><td class='it'>wenn</td><td class='it'>Immer wenn ich ihn sehe, lacht er.</td></tr><tr><td>présent ou futur</td><td class='it'>wenn</td><td class='it'>Wenn ich müde bin, trinke ich Kaffee.</td></tr><tr><td>question directe ou indirecte</td><td class='it'>wann</td><td class='it'>Wann kommst du? Ich weiß nicht, wann er kommt.</td></tr></tbody></table></div><p>Autres exemples avec <b>als</b> : <em>Als ich ein Kind war, haben wir in Rom gewohnt. Als wir in Berlin waren, haben wir viel gesehen.</em> Avec <b>wenn</b> au futur : <em>Wenn ich morgen Zeit habe, rufe ich dich an.</em> Si la subordonnée est placée avant, la principale commence par le verbe conjugué : <em>Als ich ankam, hat es geregnet.</em></p><p class='callout callout--trap'><b>wann</b> est un mot interrogatif (<em>à quelle heure ? à quel moment ?</em>) ; il ne relie pas deux propositions dans le sens temporel comme <em>als</em> et <em>wenn</em>. Le français n'a pas de correspondance automatique avec les temps : l'imparfait peut décrire une période unique (<em>quand j'étais enfant</em> → <em>als ich ein Kind war</em>) et le passé composé une répétition (<em>chaque fois qu'il est venu</em> → <em>immer wenn er gekommen ist</em>). En allemand, le choix entre <em>als</em> et <em>wenn</em> dépend du sens (fait unique ou répété) et du contexte. Et au futur, le français met le futur après <em>quand</em> (<em>quand j'arriverai</em>) alors que l'allemand reste au présent : <em>wenn ich ankomme</em>. Enfin, <b>wenn</b> signifie aussi <em>si</em> au sens conditionnel (<em>Wenn es regnet, bleibe ich zu Hause</em>), tandis que le <em>si</em> du doute est <em>ob</em> (voir la fiche sur <em>dass</em> et <em>ob</em>). <em>nachdem</em> et <em>bevor</em> sont dans la partie B1 ci-dessous ; les autres conjonctions temporelles (<em>seit, bis, während</em>) viennent aux niveaux suivants.</p><h4>B1 : nachdem et bevor</h4><p><b>nachdem</b> (après que) et <b>bevor</b> (avant que ; aussi <em>ehe</em>) introduisent des subordonnées temporelles avec le verbe à la fin. <b>nachdem</b> dit que l'action de la subordonnée s'est <b>déjà produite</b> quand commence celle de la principale, et c'est pourquoi la subordonnée est un temps <b>avant</b> :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>subordonnée</th><th>principale</th></tr></thead><tbody><tr><td>passé (textes écrits)</td><td class='it'>Nachdem ich gegessen hatte,</td><td class='it'>ging ich spazieren.</td></tr><tr><td>passé (oral)</td><td class='it'>Nachdem ich gegessen hatte,</td><td class='it'>bin ich spazieren gegangen.</td></tr><tr><td>présent</td><td class='it'>Nachdem ich gegessen habe,</td><td class='it'>gehe ich spazieren.</td></tr><tr><td>bevor</td><td class='it'>Bevor ich gehe,</td><td class='it'>rufe ich dich an.</td></tr></tbody></table></div><p>Avec <em>nachdem</em>, la subordonnée est au <b>Plusquamperfekt</b> si la principale est au passé, au <b>Perfekt</b> si la principale est au présent. Avec <em>bevor</em>, les verbes ont en général le même temps : <em>Bevor ich ging, rief ich dich an. Ruf mich an, bevor du gehst.</em></p><p class='callout callout--trap'>Avec le même sujet, le français emploie l'<em>infinitif</em> (<em>Après avoir mangé, je suis sorti ; Avant de sortir, je t'appelle</em>) et, avec des sujets différents, <em>avant que</em> + <b>subjonctif</b> (<em>avant que tu partes</em>). L'allemand emploie toujours une subordonnée avec son propre sujet et l'<b>indicatif</b> : <em>Nachdem ich gegessen hatte, ...</em>, <em>Bevor du gehst, ...</em>. Avec un nom, on peut dire <em>nach dem Essen</em> et <em>vor dem Gehen</em>.</p>"
  },
  "ref:g-nebensatz-dass": {
    title: "dass, ob et les interrogatives indirectes",
    sub: "Ich glaube, dass er kommt : le verbe va à la fin",
    body: "<p>Après des verbes de pensée, de parole ou de sentiment (<em>glauben, wissen, sagen, hoffen, denken, finden</em>), la seconde partie de la phrase s'ouvre par <b>dass</b>, et le verbe conjugué va <b>à la fin</b>. La virgule avant <em>dass</em> est obligatoire.</p><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>mot</th><th>exemple</th></tr></thead><tbody><tr><td>une affirmation</td><td class='it'>dass</td><td class='it'>Ich glaube, dass er krank ist.</td></tr><tr><td>un doute, une question oui/non</td><td class='it'>ob</td><td class='it'>Ich weiß nicht, ob er kommt.</td></tr><tr><td>une question avec mot interrogatif</td><td class='it'>wann, wo, wer, warum ...</td><td class='it'>Ich weiß nicht, wann der Zug fährt.</td></tr></tbody></table></div><p>Autres exemples : <em>Er sagt, dass er keine Zeit hat. Ich hoffe, dass du kommst. Weißt du, ob das Café offen ist? Sie fragt, wo der Bahnhof ist.</em> Après des verbes comme <em>glauben, meinen, denken, sagen</em>, on peut aussi <b>omettre dass</b>, mais alors le verbe reste en deuxième position, comme dans une phrase normale : <em>Ich glaube, er ist krank.</em></p><p class='callout callout--trap'>Le français <em>que</em> correspond à <em>dass</em> (avec le <b>double s</b> : <em>das</em> avec un seul s est l'article ou le pronom, <em>das Buch, das ich lese</em>). Mais en français <em>que</em> ne peut pas disparaître (<em>je crois qu'il est malade</em>, jamais « je crois il est malade »), alors que l'allemand peut omettre <em>dass</em> en gardant l'ordre de la principale. Et il n'y a pas de virgule devant <em>que</em> en français, alors qu'elle est obligatoire devant <em>dass</em>. Le <em>si</em> français couvre le doute et la condition ; l'allemand les sépare : <em>ob</em> pour le doute (<em>Ich weiß nicht, ob er kommt</em>), <em>wenn</em> pour la condition (<em>Wenn er kommt, ...</em>). Dans les interrogatives indirectes, l'ordre est celui de la subordonnée, pas celui de la question : <em>Ich weiß nicht, wo er wohnt</em>, pas <s>wo wohnt er</s>.</p><h4>B1 : le discours rapporté</h4><p>Pour rapporter ce que quelqu'un a dit, on emploie un verbe de communication (<em>sagen, erzählen, berichten, behaupten, meinen, fragen</em>) et une subordonnée avec <em>dass</em>. Les pronoms et les personnes s'adaptent au point de vue de celui qui rapporte :</p><div class='table-wrap'><table class='gt'><thead><tr><th>discours direct</th><th>discours rapporté</th></tr></thead><tbody><tr><td class='it'>Anna sagt: „Ich habe keine Zeit.“</td><td class='it'>Anna sagt, dass sie keine Zeit hat.</td></tr><tr><td class='it'>Tom hat gesagt: „Ich komme morgen.“</td><td class='it'>Tom hat gesagt, dass er morgen kommt.</td></tr><tr><td class='it'>Er fragt: „Kommst du mit?“</td><td class='it'>Er fragt, ob ich mitkomme.</td></tr><tr><td class='it'>Sie fragt: „Wo wohnst du?“</td><td class='it'>Sie fragt, wo ich wohne.</td></tr><tr><td class='it'>Sie sagt zu mir: „Komm bald!“</td><td class='it'>Sie sagt, ich soll bald kommen.</td></tr></tbody></table></div><p>Le temps de la phrase rapportée suit la situation : si le fait est toujours valable, le présent reste même après un verbe au Perfekt (<em>Er hat gesagt, dass er krank ist</em>) ; un fait passé par rapport au discours va au Perfekt ou au Präteritum (<em>Sie hat gesagt, dass sie in Rom gewesen ist</em>). Dans les journaux, on trouve souvent le <em>Konjunktiv I</em> (<em>Er sagt, er sei krank</em>) : à ce niveau, il suffit de le reconnaître et d'employer l'indicatif avec <em>dass</em>.</p><p>Les <b>questions</b> rapportées emploient <em>ob</em> (questions oui/non) ou le mot interrogatif (<em>wo, wann, warum</em>), toujours avec le verbe à la fin. Un <b>ordre</b> ou une demande se rapporte avec <em>sollen</em> (<em>Sie sagt, ich soll kommen</em>) ou avec <em>bitten ... zu</em> (<em>Sie bat mich, zu kommen</em>).</p><p class='callout callout--trap'>Le français rapporté applique la <em>concordance des temps</em> (<em>Il a dit qu'il n'avait pas le temps</em>). L'allemand, pour un fait encore valable, garde le présent : <em>Er hat gesagt, dass er keine Zeit hat</em>. Dans la presse, le français emploie le conditionnel (<em>il serait malade</em>) là où l'allemand a le Konjunktiv I (<em>er sei krank</em>). Comme en français, la question rapportée n'a pas l'ordre de la question directe, mais en allemand le verbe va à la fin : <em>Er fragt, ob ich komme</em>, pas <s>ob komme ich</s>.</p>"
  },
  "ref:g-infinitiv-zu": {
    title: "L'infinitif avec zu",
    sub: "Ich habe Lust, ins Kino zu gehen : zu + infinitif à la fin",
    body: "<p>Après beaucoup d'expressions, le verbe suivant est à l'infinitif précédé de <b>zu</b>, à la fin de la phrase : <em>Ich habe Lust, ins Kino zu gehen. Ich habe vor, im Sommer nach Wien zu fahren. Es ist wichtig, früh aufzustehen.</em></p><div class='table-wrap'><table class='gt'><thead><tr><th>expression</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>Lust/Zeit haben</td><td class='it'>Ich habe keine Zeit, einkaufen zu gehen.</td></tr><tr><td class='it'>vorhaben</td><td class='it'>Wir haben vor, Deutsch zu lernen.</td></tr><tr><td class='it'>anfangen, aufhören</td><td class='it'>Er hört auf, im Büro zu arbeiten.</td></tr><tr><td class='it'>versuchen, vergessen</td><td class='it'>Ich versuche, dich zu verstehen.</td></tr><tr><td class='it'>es ist schön/wichtig/schwer ...</td><td class='it'>Es ist schön, dich zu sehen.</td></tr></tbody></table></div><p>Avec les verbes séparables, <em>zu</em> se place <b>entre le préfixe et le verbe</b>, et tout s'écrit d'une traite : <em>aufstehen → aufzustehen, einkaufen → einzukaufen</em>. Quand le groupe de l'infinitif est <b>étendu</b> (<em>zu</em> + d'autres mots), on met la virgule : <em>Ich habe keine Lust, heute zu arbeiten. Ich versuche, mehr Deutsch zu sprechen.</em> Avec <em>um/ohne/statt ... zu</em>, elle est toujours obligatoire. Avec un simple <em>zu</em> + infinitif après un verbe, la virgule est facultative : <em>Ich fange an zu arbeiten</em> ou <em>Ich fange an, zu arbeiten</em>. Les verbes modaux et <em>werden</em> ne veulent pas de <em>zu</em> : <em>Ich muss gehen. Ich werde kommen.</em></p><p>Si le sujet change, on emploie en général <em>dass</em> plutôt que l'infinitif : <em>Ich möchte, dass du kommst.</em> Les constructions <em>um ... zu</em>, <em>ohne ... zu</em>, <em>statt ... zu</em> viennent aux niveaux suivants.</p><p class='callout callout--trap'>Le français relie les verbes avec des prépositions qui changent selon le verbe (<em>j'ai envie d'aller, je commence à travailler, j'arrête de fumer, j'essaie de comprendre</em>), à apprendre une par une. Dans les exemples de ce paragraphe, l'allemand n'a qu'une construction, <em>zu</em> + infinitif, sans préposition qui change selon le verbe : <em>Ich fange an zu arbeiten, ich höre auf zu rauchen</em> (la particule séparable <em>an-/auf-</em> fait partie du verbe, ce n'est pas une préposition). Certains verbes veulent pourtant un complément prépositionnel avant le <em>zu</em> (<em>davon träumen, … zu …</em>, <em>darauf warten, … zu …</em>) : on l'apprend avec le verbe. Comme en français après <em>vouloir, pouvoir, devoir</em> (<em>je veux venir</em>), les modaux allemands se construisent sans <em>zu</em> : <em>Ich will kommen</em>. Et il n'y a pas de virgule devant l'infinitif en français, alors qu'en allemand le groupe étendu en prend une.</p><h4>B2 : ohne ... zu, statt ... zu</h4><p><b>ohne ... zu</b> (<em>sans</em> + infinitif) et <b>statt / anstatt ... zu</b> (<em>au lieu de</em> + infinitif) forment une proposition infinitive qui a le même sujet que la principale ; <em>zu</em> + infinitif se place à la fin : <em>Er ging, ohne sich zu verabschieden. Statt zu warten, rief sie sofort an.</em> Avec un verbe séparable, <em>zu</em> se glisse entre la particule et le verbe : <em>ohne aufzustehen</em>.</p><p>Si le sujet est différent, on emploie <b>ohne dass</b> ou <b>anstatt dass</b> avec le verbe conjugué à la fin : <em>Er ging, ohne dass ich es merkte. Anstatt dass du hilfst, schaust du nur zu.</em></p><p class='callout callout--trap'>En français l'infinitif suit directement la préposition (<em>sans dire au revoir</em>) ; en allemand l'infinitif avec <em>zu</em> va à la fin de la proposition : <em>ohne mich zu fragen</em>. Et après <em>sans que</em> le français demande le subjonctif (<em>sans que je le remarque</em>), alors qu'après <em>ohne dass</em> l'allemand garde l'indicatif : <em>ohne dass ich es merkte</em>.</p>"
  },
  "ref:g-relativsatz": {
    title: "La proposition relative",
    sub: "Das Buch, das ich gelesen habe : der, die, das + verbe à la fin",
    body: "<p>La proposition relative donne une information sur un nom. Elle commence par un <b>pronom relatif</b>, a le verbe conjugué <b>à la fin</b> et se place <b>entre virgules</b>. Le pronom relatif prend le <b>genre et le nombre</b> du nom auquel il se rapporte, et le <b>cas</b> de sa fonction dans la relative. Dans les trois cas du tableau, les formes sont celles de l'article défini, sauf au datif pluriel (le génitif relatif, <em>dessen, deren</em>, viendra plus tard) :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>m.</th><th>f.</th><th>n.</th><th>pluriel</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>der</td><td class='it'>die</td><td class='it'>das</td><td class='it'>die</td></tr><tr><td>accusatif</td><td class='it'>den</td><td class='it'>die</td><td class='it'>das</td><td class='it'>die</td></tr><tr><td>datif</td><td class='it'>dem</td><td class='it'>der</td><td class='it'>dem</td><td class='it'>denen</td></tr></tbody></table></div><div class='table-wrap'><table class='gt'><thead><tr><th>cas</th><th>exemple</th></tr></thead><tbody><tr><td>nominatif</td><td class='it'>Der Mann, <b>der</b> dort steht, ist mein Lehrer.</td></tr><tr><td>accusatif</td><td class='it'>Das Buch, <b>das</b> ich gelesen habe, ist spannend.</td></tr><tr><td>datif</td><td class='it'>Die Frau, <b>der</b> ich geholfen habe, heißt Eva.</td></tr><tr><td>datif pluriel</td><td class='it'>Die Kinder, <b>denen</b> ich das Buch gebe, sind sieben.</td></tr></tbody></table></div><h4>Avec une préposition</h4><p>La préposition se place <b>avant</b> le pronom et décide du cas : <em>Der Mann, mit dem ich spreche, ist mein Chef. Das Thema, über das wir sprechen, ist wichtig. Die Freundin, auf die ich warte, kommt aus Rom.</em></p><h4>was après alles, nichts, etwas</h4><p>Après <em>alles, nichts, etwas, vieles</em> et après un superlatif neutre, le pronom est <b>was</b> : <em>Alles, was du sagst, ist richtig. Das ist das Beste, was ich je gegessen habe.</em> On emploie aussi <em>was</em> pour renvoyer à toute la phrase précédente : <em>Er hat gewonnen, was mich freut.</em></p><p class='callout callout--trap'>Le français choisit lui aussi le pronom selon la fonction (<em>l'homme <b>qui</b> parle</em>, sujet ; <em>l'homme <b>que</b> je vois</em>, objet direct), mais <em>qui</em> et <em>que</em> ne changent ni en genre ni en nombre. L'allemand ajoute le genre et le nombre du nom : <em>Der Mann, <b>der</b> kommt</em> (sujet), <em>die Frau, <b>die</b> kommt</em>, <em>der Mann, <b>den</b> ich sehe</em> (objet direct). Avant d'écrire la relative, demande-toi : quel est le rôle du pronom <b>dans</b> la relative ? Après une préposition, le cas dépend du verbe allemand, pas du français : <em>le thème dont nous parlons</em> se dit <em>das Thema, über das wir sprechen</em>, et <em>dont</em> n'a pas de forme unique.</p><p class='callout callout--trap'>En allemand, la relative est <b>toujours</b> entre virgules, même quand le français n'en met pas (<em>l'homme que tu vois est mon oncle</em>, mais <em>Der Mann, den du siehst, ist mein Onkel</em>). Et le français a un seul <em>que</em> pour la relative et pour la conjonction (<em>le livre que je lis, je crois que ...</em>), alors que l'allemand sépare le pronom <em>das</em> (<em>das Buch, das ich lese</em>) de la conjonction <em>dass</em> (<em>Ich glaube, dass ...</em>).</p>"
  },
  "ref:g-konditionalsatz": {
    title: "La condition avec wenn",
    sub: "Wenn es regnet, ... ; Wenn ich Zeit hätte, ... : réel et irréel",
    body: "<p><b>wenn</b> (si) introduit une subordonnée : le verbe conjugué va <b>à la fin</b> et il y a une virgule. Si la phrase avec <em>wenn</em> est en tête, la principale commence par le <b>verbe conjugué</b>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>phrase avec wenn</th><th>principale</th></tr></thead><tbody><tr><td>réel (possible)</td><td class='it'>Wenn es regnet,</td><td class='it'>bleibe ich zu Hause.</td></tr><tr><td>réel, avec le futur</td><td class='it'>Wenn ich morgen Zeit habe,</td><td class='it'>rufe ich dich an.</td></tr><tr><td>irréel (présent)</td><td class='it'>Wenn ich Zeit hätte,</td><td class='it'>würde ich kommen.</td></tr><tr><td>irréel (présent)</td><td class='it'>Wenn ich du wäre,</td><td class='it'>würde ich ihm schreiben.</td></tr></tbody></table></div><p>Dans la condition <b>réelle</b>, les verbes sont à l'indicatif, en général au Präsens dans les deux phrases, même pour le futur. Dans la condition <b>irréelle</b> (une situation qui n'existe pas ou qui est improbable), le Konjunktiv II est la forme normale : <em>hätte, wäre, könnte</em> avec les verbes fréquents, <em>würde + infinitif</em> avec les autres. Les deux constructions peuvent apparaître dans les deux parties : <em>Wenn ich weniger arbeiten würde, hätte ich mehr Zeit.</em> Pour une chose possible mais peu probable, on peut aussi employer le Konjunktiv II : <em>Wenn es morgen regnen würde, ...</em></p><p>Pour une condition possible, on peut aussi employer <b>falls</b> (au cas où) : <em>Falls du Zeit hast, ruf mich an.</em> Sans <em>wenn</em>, la condition irréelle peut s'ouvrir par le verbe : <em>Hätte ich Zeit, würde ich kommen.</em></p><p class='callout callout--trap'>Pour l'irréel, le français a l'<em>imparfait</em> après <em>si</em> et le <em>conditionnel</em> dans la conséquence (<em>Si j'avais le temps, je viendrais</em>). L'allemand emploie le Konjunktiv II dans les deux parties, ou <em>würde</em> + infinitif : <em>Wenn ich Zeit hätte, käme ich</em> ou <em>würde ich kommen</em>. Le français ne met pas le conditionnel après <em>si</em> ; en allemand, <em>würde</em> après <em>wenn</em> est possible, surtout avec des verbes comme <em>arbeiten</em>, mais avec <em>haben</em> et <em>sein</em> on préfère la forme propre (<em>Wenn ich Zeit hätte</em>).</p><p class='callout callout--trap'>Après un <em>si</em> réel, le français met le présent dans le <em>si</em> et le futur dans la principale (<em>Si j'ai le temps demain, je t'appellerai</em>) ; l'allemand emploie le <b>Präsens</b> partout : <em>Wenn ich morgen Zeit habe, rufe ich dich an</em>. Et si la phrase avec <em>wenn</em> vient en premier, le français ne change pas l'ordre de la principale, l'allemand, si : <em>Wenn es regnet, <b>bleibe ich</b> zu Hause</em>.</p><h4>B2 : le système hypothétique au passé et ses variantes</h4><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>exemple</th></tr></thead><tbody><tr><td>réel</td><td class='it'>Wenn es regnet, bleibe ich zu Hause.</td></tr><tr><td>irréel, présent</td><td class='it'>Wenn ich Zeit hätte, käme ich mit.</td></tr><tr><td>irréel, passé</td><td class='it'>Wenn ich Zeit gehabt hätte, wäre ich mitgekommen.</td></tr><tr><td>mixte</td><td class='it'>Wenn ich gestern früher ins Bett gegangen wäre, wäre ich jetzt nicht so müde.</td></tr></tbody></table></div><ul><li><b>falls</b> (<em>au cas où, si jamais</em>) : une condition possible, moins sûre qu'avec <em>wenn</em>. <em>Falls es regnet, nehmen wir den Bus.</em></li><li><b>sofern</b> (<em>pourvu que, à condition que</em>), plus soutenu : <em>Sofern nichts dazwischenkommt, sind wir um acht da.</em></li><li><b>es sei denn</b> (<em>à moins que</em>) est suivi d'une proposition avec le verbe en deuxième position : <em>Wir gehen spazieren, es sei denn, es regnet.</em></li><li><b>sans wenn</b> : le verbe conjugué se place en tête, et la principale commence souvent par <em>dann</em> ou <em>so</em>. <em>Hätte ich das gewusst, (dann) wäre ich gekommen. Regnet es, bleiben wir zu Hause.</em></li></ul><p class='callout callout--trap'><em>À moins qu'il (ne) pleuve</em> : le français demande le subjonctif, et le <em>ne</em> explétif, facultatif, ne nie rien. <em>es sei denn</em> se construit avec l'indicatif et sans négation : <em>es sei denn, es regnet</em> ; avec <em>nicht</em>, la phrase dirait le contraire. Et <em>au cas où</em> appelle le conditionnel (<em>au cas où il pleuvrait</em>), alors que <em>falls</em> prend l'indicatif : <em>falls es regnet</em>.</p>"
  },
  "ref:g-konzessiv": {
    title: "La concession : obwohl et trotzdem",
    sub: "obwohl es regnet : le verbe va à la fin ; Trotzdem gehe ich : le verbe est en deuxième position",
    body: "<p><b>obwohl</b> (bien que, quoique) introduit une subordonnée qui dit quelque chose qu'on s'attendrait à voir comme un obstacle, et qui n'en est pas un. Le verbe conjugué va <b>à la fin</b>, avec la virgule.</p><p><em>Obwohl es regnet, gehe ich spazieren. Ich gehe spazieren, obwohl es regnet.</em> Si la subordonnée est en tête, la principale commence par le verbe conjugué. <em>Obwohl</em> et <em>trotzdem</em> peuvent aussi apparaître ensemble, et la principale en est renforcée : <em>Obwohl es regnet, gehen wir trotzdem spazieren.</em></p><p>La même idée peut se dire de trois façons, avec trois ordres différents :</p><div class='table-wrap'><table class='gt'><thead><tr><th>mot</th><th>type</th><th>ordre</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>aber</td><td>conjonction (position zéro)</td><td>verbe en deuxième position</td><td class='it'>Es regnet, aber ich gehe spazieren.</td></tr><tr><td class='it'>trotzdem</td><td>adverbe (première position)</td><td>verbe juste après</td><td class='it'>Es regnet. Trotzdem gehe ich spazieren.</td></tr><tr><td class='it'>obwohl</td><td>conjonction de subordination</td><td>verbe à la fin</td><td class='it'>Ich gehe spazieren, obwohl es regnet.</td></tr></tbody></table></div><p>Avec un nom, on emploie la préposition <b>trotz</b> + génitif : <em>Trotz des Regens gehe ich spazieren.</em> (à l'oral aussi avec le datif).</p><p class='callout callout--trap'>Le français <em>bien que</em> veut le <b>subjonctif</b> (<em>Bien qu'il pleuve, je sors</em>). Avec <em>obwohl</em>, un fait réel se dit normalement à l'<b>indicatif</b> : <em>Obwohl es regnet</em>. Le tour français le plus proche est <em>même si</em> avec l'indicatif (<em>Je sors même s'il pleut</em>), quand le fait est réel. <em>malgré</em> correspond à <em>trotz</em> et <em>pourtant, quand même</em> à <em>trotzdem</em>.</p><p class='callout callout--trap'><em>même si</em> vaut en français aussi pour une hypothèse (<em>Même s'il pleuvait, je sortirais</em>). En allemand, l'hypothèse se dit avec <b>auch wenn</b> ou <b>selbst wenn</b>, pas avec <em>obwohl</em>, qui sert pour un fait réel : <em>Auch wenn es morgen regnet, gehe ich spazieren.</em> Et <em>obwohl</em> n'est pas <em>weil</em> : <em>weil</em> introduit une cause ; <em>obwohl</em> introduit un fait malgré lequel se produit ce que dit la principale.</p><h4>B2 : obgleich, trotz, auch wenn, selbst wenn</h4><p><b>obgleich</b> et <b>obschon</b> signifient <em>obwohl</em> mais sont plus soutenus ; le verbe va à la fin. La même concession peut s'exprimer de trois façons :</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>exemple</th></tr></thead><tbody><tr><td>subordonnée : obwohl</td><td class='it'>Obwohl es regnete, gingen wir spazieren.</td></tr><tr><td>adverbe : trotzdem</td><td class='it'>Es regnete. Trotzdem gingen wir spazieren.</td></tr><tr><td>préposition : trotz + génitif</td><td class='it'>Trotz des Regens gingen wir spazieren.</td></tr></tbody></table></div><p>À l'oral, <em>trotz</em> se rencontre aussi avec le datif (<em>trotz dem Regen</em>) ; à l'écrit, il régit le génitif. <b>auch wenn</b> et <b>selbst wenn</b> (<em>même si</em>) introduisent une hypothèse : <em>Selbst wenn ich Zeit hätte, würde ich nicht mitkommen.</em></p><p class='callout callout--trap'><em>Bien qu'il pleuve</em> : le français met le subjonctif après <em>bien que</em> et <em>quoique</em> ; l'allemand met l'indicatif après <em>obwohl</em> et <em>obgleich</em> : <em>obwohl es regnet</em>. <em>Malgré</em> se construit avec un nom comme <em>trotz</em> (<em>malgré la pluie</em>, <em>trotz des Regens</em>), mais <em>malgré le fait que</em> devant une proposition se dit simplement <em>obwohl</em>.</p>"
  },
  "ref:g-nebensatz-final": {
    title: "La finale : um ... zu et damit",
    sub: "Ich lerne Deutsch, um in Berlin zu arbeiten : le but",
    body: "<p>Pour dire le <b>but</b> d'une action (la réponse à <em>Wozu? Wofür?</em>), il y a deux constructions.</p><div class='table-wrap'><table class='gt'><thead><tr><th>construction</th><th>quand</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>um ... zu + infinitif</td><td>même sujet dans les deux parties</td><td class='it'>Ich lerne Deutsch, um in Berlin zu arbeiten.</td></tr><tr><td class='it'>damit + phrase avec le verbe à la fin</td><td>sujets différents</td><td class='it'>Ich rufe an, damit er Bescheid weiß.</td></tr></tbody></table></div><p>Avec <b>um ... zu</b>, l'infinitif est à la fin et <em>zu</em> se place juste avant le verbe ; avec un verbe séparable, <em>zu</em> va au milieu : <em>um früh aufzustehen, um pünktlich anzukommen</em>. Devant <em>um</em>, la virgule est obligatoire. Après <b>damit</b>, il y a un verbe conjugué à l'<b>indicatif</b>, à la fin : <em>Ich erkläre es noch einmal, damit du es verstehst.</em></p><p>Même avec le même sujet, <em>damit</em> est possible (<em>Ich gehe früh, damit ich pünktlich bin</em>), mais <em>um ... zu</em> est la forme la plus naturelle. Avec des sujets différents, on ne peut pas employer <em>um ... zu</em> : <s>Ich rufe an, um er Bescheid weiß</s>.</p><p>Avec un nom, on peut employer <b>für</b> : <em>Ich lerne für die Prüfung.</em> Pour le but d'une action, on emploie en revanche <em>um ... zu</em>.</p><p class='callout callout--trap'>Le français emploie <em>pour</em> + infinitif (<em>Je travaille pour gagner de l'argent</em>) et, avec des sujets différents, <em>pour que</em> ou <em>afin que</em> + <b>subjonctif</b> (<em>Je t'écris pour que tu saches</em>). L'allemand emploie <em>um ... zu</em> et <em>damit</em> avec l'<b>indicatif</b>. <em>pour</em> seul ne suffit pas : <em>Ich arbeite, um Geld zu verdienen</em>, pas <s>für Geld zu verdienen</s>.</p><p class='callout callout--trap'>Le mot français <em>pour</em> correspond à plusieurs mots allemands : <em>um ... zu</em> devant un infinitif, <em>damit</em> devant un autre sujet, <em>für</em> devant un nom (<em>pour toi</em> se dit <em>für dich</em>). Le but et la cause sont déjà deux mots en français (<em>pour que</em> et <em>parce que</em>), comme en allemand : <em>damit</em> pour le but, <em>weil</em> pour la cause. L'erreur à éviter est de prendre <em>damit</em> après un verbe de volonté : <em>Je veux que tu viennes</em> se dit <em>Ich will, dass du kommst</em>.</p>"
  },
  "ref:g-aussprache": {
    title: "Prononciation de base",
    sub: "ä ö ü, ß, ch, sch, sp/st, w, v, z, ei/ie, eu/äu",
    body: "<h4>Voyelles</h4><ul><li><b>ü</b> = le <em>u</em> français (<em>tu</em>) : <em>über, Tür</em>. Bonne nouvelle : vous l'avez déjà. Par contre le <b>u</b> allemand = le <em>ou</em> français : <em>Hut, gut</em>.</li><li><b>ö</b> = <em>eu</em> : <em>schön</em> comme <em>peu</em>, <em>öffnen</em> comme <em>peur</em>. <b>ä</b> = <em>è</em> : <em>Käse</em>.</li><li><b>ei</b> = <em>aï</em> (<em>nein, mein</em>) ; <b>ie</b> = <em>i</em> long (<em>Liebe, Tier</em>) ; <b>eu / äu</b> = <em>oï</em> (<em>Freund, Häuser</em>), pas le <em>eu</em> français.</li><li>Pas de voyelles nasales : dans <em>Anna, Wand, Zimmer</em> le <em>n</em> et le <em>m</em> se prononcent.</li></ul><h4>Consonnes</h4><ul><li><b>ch</b> : après <em>a, o, u, au</em>, un son rauque [x] (<em>Bach, Buch</em>), proche du <em>r</em> français, sans vibrer ; après les autres voyelles et les consonnes, un souffle doux [ç] (<em>ich, Milch</em>), y compris après <em>äu</em> et <em>eu</em> (<em>euch</em>), la langue placée comme pour <em>i</em>. Exceptions : <em>chs</em> = [ks] quand le <em>s</em> fait partie du radical (<em>wachsen, sechs, Fuchs</em> ; si le <em>s</em> est une terminaison, <em>ch</em> garde son son : <em>machst, höchste</em>), <em>-ig</em> final = [ɪç] (<em>König</em>), et <em>ch</em> = [k] dans quelques mots d'emprunt (<em>Chor, Charakter</em>).</li><li><b>sch</b> = <em>ch</em> français (<em>Schule</em>) ; <b>sp / st</b> en début de mot = <em>chp / cht</em> (<em>Sport, Stein</em>).</li><li><b>w</b> = <em>v</em> (<em>Wasser</em>) ; <b>v</b> = <em>f</em> dans les mots d'origine allemande (<em>Vater</em>), mais <em>v</em> dans des emprunts (<em>Video, Vase</em>) ; <b>z</b> = <em>ts</em> (<em>Zeit</em>) ; <b>ß</b> = <em>ss</em> sourd (<em>Straße</em>).</li><li><b>h</b> en début de mot se prononce, un léger souffle (<em>Haus</em>) ; le <em>h</em> d'allongement après une voyelle ne se prononce pas (<em>fahren, wohnen</em>), pas plus que le <em>h</em> entre deux voyelles (<em>sehen, gehen</em>), qui sépare les syllabes.</li><li><b>Consonne finale sourde</b> : <em>Tag</em> [taːk], <em>Hund</em> [hʊnt], <em>Bad</em> [baːt] : la consonne s'assourdit, la voyelle longue reste longue.</li></ul><p class='callout callout--trap'>L'accent tonique tombe le plus souvent sur la <b>première syllabe du radical</b> (<em>ARbeiten, WOhnung</em>), pas sur la dernière comme en français. Les préfixes <em>be-, ver-</em> ne portent pas l'accent : <em>beSUchen, verSTEhen</em>.</p>"
  },
  "ref:g-register": {
    title: "Tutoiement, vouvoiement et salutations",
    sub: "du et Sie ; Guten Tag, Tschüss, Auf Wiedersehen",
    body: "<h4>du ou Sie</h4><ul><li><b>du</b> : famille, amis, enfants, étudiants entre eux, et souvent entre collègues.</li><li><b>Sie</b> : inconnus, adultes dans un cadre formel, commerces et administrations, supérieurs. Le verbe est à la 3<sup>e</sup> personne du pluriel : <em>Wie heißen Sie? Woher kommen Sie?</em> Avec <em>Herr</em> ou <em>Frau</em> + nom de famille : <em>Herr Müller, Frau Schmidt</em>.</li></ul><p>L'usage ressemble à <em>tu / vous</em>, mais attention : le français <em>vous</em> sert aussi pour le pluriel ; en allemand, plusieurs amis se disent <em>ihr</em>.</p><h4>Salutations</h4><ul><li><em>Guten Morgen</em> (le matin), <em>Guten Tag</em> (en journée), <em>Guten Abend</em> (le soir), <em>Gute Nacht</em> (avant de dormir ou pour prendre congé tard le soir ; jamais comme salutation d'arrivée).</li><li>Informel : <em>Hallo</em> pour dire bonjour, <em>Tschüss</em> pour dire au revoir. Formel : <em>Auf Wiedersehen</em>. Aussi <em>Bis später, Bis bald</em>.</li></ul><h4>À reconnaître</h4><p><em>Grüß Gott</em> et <em>Servus</em> (Bavière, Autriche : bonjour, et <em>Servus</em> aussi au revoir), <em>Moin</em> (nord de l'Allemagne, à toute heure). Vous les entendrez, vous n'avez pas à les employer.</p>"
  },
  "ref:g-modalpartikeln": {
    title: "Les particules modales",
    sub: "mal, doch, ja, halt, eben, wohl, etwa : elles expriment la certitude, les attentes et les intentions du locuteur",
    body: "<p>Les <b>particules modales</b> sont de petits mots (<em>mal, doch, ja, halt, eben, wohl, etwa</em>) que le locuteur glisse dans la phrase pour dire <b>ce qu'il en pense</b> : surprise, insistance, résignation, politesse. Sans la particule, la phrase reste correcte, mais elle change : cela peut modifier le degré de certitude, ce que le locuteur attend ou son intention (<em>Er ist wohl krank</em> est une supposition, <em>Er ist krank</em> une affirmation). On les emploie surtout à l'oral et dans l'écrit familier, et elles n'ont presque jamais de traduction exacte.</p><div class='table-wrap'><table class='gt'><thead><tr><th>particule</th><th>effet</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>mal</td><td>adoucit une demande, une invitation</td><td class='it'>Komm mal her! Kannst du mal helfen?</td></tr><tr><td class='it'>doch</td><td>encourage ou rappelle quelque chose</td><td class='it'>Komm doch mit! Das ist doch klar.</td></tr><tr><td class='it'>ja</td><td>c'est une chose connue, une surprise</td><td class='it'>Das ist ja toll! Ich bin ja müde.</td></tr><tr><td class='it'>halt / eben</td><td>c'est ainsi, on n'y peut rien</td><td class='it'>Das ist halt so.</td></tr><tr><td class='it'>wohl</td><td>supposition</td><td class='it'>Er ist wohl krank.</td></tr><tr><td class='it'>etwa</td><td>dans la question : doute, soupçon</td><td class='it'>Bist du etwa krank?</td></tr></tbody></table></div><p>Les particules se placent dans le champ central, en général après le verbe et après les pronoms : <em>Ich habe dir doch gesagt, dass ...</em> Le sens dépend du ton et du contexte : mieux vaut les apprendre dans des phrases entières, en les écoutant.</p><p class='callout callout--trap'>Beaucoup ont des <b>homonymes</b> à autre fonction : <em>doch</em> est aussi la réponse à une question négative (<em>Hast du keine Zeit? Doch!</em>, comme le <em>si</em> français : <em>Mais si !</em>), <em>mal</em> veut aussi dire <em>fois</em> (<em>einmal</em>), <em>wohl</em> veut aussi dire <em>bien</em> (<em>sich wohlfühlen</em>). Le français rend ces nuances par d'autres mots ou par l'intonation : <em>mal</em> se rapproche de <em>un peu</em> (<em>viens un peu ici</em>), <em>doch</em> de <em>donc</em> ou <em>allez</em> (<em>viens donc !</em>), <em>wohl</em> de <em>sans doute</em>, <em>etwa</em> de <em>par hasard</em>. Ce sont des équivalences approximatives, pas des traductions.</p><h4>B2 : bloß et nur dans les souhaits</h4><p>Dans les souhaits irréels, <b>bloß</b>, <b>nur</b> et <b>doch</b> renforcent le Konjunktiv II : <em>Wenn ich bloß mehr Zeit hätte! Hätte ich nur nicht so viel gegessen! Wäre ich doch zu Hause geblieben!</em> Dans les injonctions, <em>bloß</em> et <em>ja</em> rendent l'ordre plus insistant ou menaçant : <em>Mach das bloß nicht! Komm ja nicht zu spät!</em></p><p class='callout callout--trap'>Ici <em>nur</em> et <em>bloß</em> ne veulent pas dire <em>seulement</em> : ils correspondent au <em>si seulement</em> français. L'allemand peut omettre <em>wenn</em> en mettant le verbe en tête (<em>Hätte ich nur ...!</em>), et la particule se place après le sujet, avant la négation.</p>"
  },
  "ref:g-werden": {
    title: "Les fonctions de werden",
    sub: "Er wird Arzt, er wird anrufen, das wird gemacht, er würde, er wird wohl müde sein",
    body: "<p><b>werden</b> a cinq fonctions, et un texte de niveau C1 les emploie toutes. Pour les reconnaître, regardez ce qui l'accompagne.</p><div class='table-wrap'><table class='gt'><thead><tr><th>fonction</th><th>ce qui l'accompagne</th><th>exemple</th></tr></thead><tbody><tr><td>verbe plein « devenir »</td><td>un nom ou un adjectif</td><td class='it'>Er wird Arzt. Es wird dunkel.</td></tr><tr><td>futur</td><td>un infinitif</td><td class='it'>Ich werde dich anrufen.</td></tr><tr><td>supposition</td><td>un infinitif, souvent avec wohl</td><td class='it'>Sie wird wohl im Büro sein.</td></tr><tr><td>passif</td><td>un participe passé</td><td class='it'>Das Haus wird renoviert.</td></tr><tr><td>Konjunktiv II</td><td>la forme würde + infinitif</td><td class='it'>Ich würde gern mitkommen.</td></tr></tbody></table></div><p>Au Perfekt, le verbe plein a <em>geworden</em> (<em>Er ist Arzt geworden</em>), le passif <em>worden</em> (<em>Das Haus ist renoviert worden</em>). Futur et supposition ont la même forme : le contexte et des adverbes comme <em>wohl</em> décident.</p><p class='callout callout--trap'>Le français répartit ces fonctions entre des formes différentes : <em>devenir</em>, le futur simple (<em>j'appellerai</em>), <em>devoir</em> pour la supposition, <em>être</em> au passif, le conditionnel (<em>je viendrais</em>). En allemand c'est toujours <em>werden</em>, et une erreur fréquente consiste à lire <em>Das Haus wird renoviert</em> comme un futur : c'est un passif présent, « la maison est en cours de rénovation ».</p>"
  },
  "ref:g-funktionsverbgefuege": {
    title: "Les locutions verbales",
    sub: "eine Entscheidung treffen, zur Verfügung stellen, in Frage kommen",
    body: "<p>Dans les textes formels, beaucoup d'actions s'expriment par un <b>nom</b> qui porte le sens et un <b>verbe</b> presque vide (<em>stellen, kommen, nehmen, treffen, bringen, finden</em>) : c'est le <em>Funktionsverbgefüge</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>locution</th><th>verbe simple</th><th>sens</th></tr></thead><tbody><tr><td class='it'>eine Entscheidung treffen</td><td class='it'>entscheiden</td><td>prendre une décision</td></tr><tr><td class='it'>zur Verfügung stellen</td><td class='it'>bereitstellen</td><td>mettre à disposition</td></tr><tr><td class='it'>in Frage kommen</td><td class='it'>möglich sein</td><td>entrer en ligne de compte</td></tr><tr><td class='it'>zum Ausdruck bringen</td><td class='it'>ausdrücken</td><td>exprimer</td></tr><tr><td class='it'>in Kraft treten</td><td class='it'>gültig werden</td><td>entrer en vigueur</td></tr><tr><td class='it'>Rücksicht nehmen auf</td><td class='it'>berücksichtigen</td><td>tenir compte de, ménager</td></tr><tr><td class='it'>Anwendung finden</td><td class='it'>angewendet werden</td><td>s'appliquer</td></tr></tbody></table></div><p>Le groupe est figé : on ne choisit ni la préposition ni l'article (<em>zur Verfügung</em>). Certains ont une valeur passive (<em>Anwendung finden, zur Sprache kommen</em>), d'autres marquent le début d'une action (<em>in Gang bringen</em>). Dans la phrase, le nom va vers la fin, comme une particule séparable : <em>Die Firma stellt uns die Räume zur Verfügung.</em></p><p class='callout callout--trap'>Le français a des locutions comparables (<em>prendre une décision</em>, <em>mettre à disposition</em>, <em>entrer en vigueur</em>), et beaucoup se correspondent. Le risque est le calque là où elles diffèrent : <em>prendre une décision</em> se dit avec <em>treffen</em>, pas <em>nehmen</em> ; <em>poser une question</em> est <em>eine Frage stellen</em> ; <em>prendre en considération</em> est <em>in Betracht ziehen</em>.</p>"
  },
  "ref:g-nominalstil": {
    title: "Le style nominal",
    sub: "Nach Abschluss der Arbeiten : le nom à la place de la proposition",
    body: "<p>Dans les textes administratifs, juridiques et universitaires, l'allemand transforme les verbes en noms et les subordonnées en groupes prépositionnels : c'est le <b>Nominalstil</b>. Le même contenu devient plus compact et plus impersonnel.</p><div class='table-wrap'><table class='gt'><thead><tr><th>style verbal</th><th>style nominal</th></tr></thead><tbody><tr><td class='it'>Nachdem die Arbeiten abgeschlossen worden sind, ...</td><td class='it'>Nach Abschluss der Arbeiten ...</td></tr><tr><td class='it'>Weil es stark regnete, ...</td><td class='it'>Wegen des starken Regens ...</td></tr><tr><td class='it'>Wenn Sie den Antrag zu spät abgeben, ...</td><td class='it'>Bei verspäteter Abgabe des Antrags ...</td></tr><tr><td class='it'>Um die Kosten zu senken, ...</td><td class='it'>Zur Senkung der Kosten ...</td></tr><tr><td class='it'>Während wir verhandelten, ...</td><td class='it'>Während der Verhandlungen ...</td></tr></tbody></table></div><p>Les outils sont les noms en <em>-ung, -heit, -keit</em>, l'infinitif substantivé (<em>das Lesen</em>), le génitif pour le complément du verbe (<em>die Senkung der Kosten</em>) et des prépositions comme <em>wegen, trotz, bei, nach, vor, zu, während</em>. C'est le style de l'écrit formel et de la langue administrative (<em>Amtsdeutsch</em>) ; à l'oral et dans les textes faits pour être lus facilement, on préfère le style verbal, qui reste aussi quand la subordonnée porte beaucoup d'informations.</p><p class='callout callout--trap'>Le français administratif nominalise lui aussi (<em>après achèvement des travaux</em>, <em>en cas de remise tardive</em>), et la structure paraît donc familière. La différence est dans les cas : le complément du verbe devient un génitif (<em>die Kosten senken</em> → <em>die Senkung der Kosten</em>), là où le français met toujours <em>de</em>.</p>"
  },
  "ref:g-partizipialattribut": {
    title: "Le participe épithète",
    sub: "der lachende Mann, das gestern gekaufte Buch",
    body: "<p>Le <b>participe I</b> (infinitif + <em>-d</em>) et le <b>participe II</b> s'emploient devant le nom comme des adjectifs et se déclinent comme des adjectifs. Le participe I exprime une action simultanée et active (<em>der lachende Mann</em>, l'homme qui rit) ; le participe II en général une action achevée (<em>das gekaufte Buch</em>, le livre acheté).</p><p>D'autres compléments peuvent précéder le participe : tout le groupe se place entre l'article et le nom, et c'est la façon compacte de dire une relative (<em>erweitertes Partizipialattribut</em>).</p><div class='table-wrap'><table class='gt'><thead><tr><th>relative</th><th>participe épithète</th></tr></thead><tbody><tr><td class='it'>das Buch, das gestern gekauft wurde</td><td class='it'>das gestern gekaufte Buch</td></tr><tr><td class='it'>die Kinder, die im Garten spielen</td><td class='it'>die im Garten spielenden Kinder</td></tr><tr><td class='it'>die Kosten, die stark gestiegen sind</td><td class='it'>die stark gestiegenen Kosten</td></tr><tr><td class='it'>ein Problem, das gelöst werden muss</td><td class='it'>ein zu lösendes Problem</td></tr></tbody></table></div><p>La dernière forme (<em>zu</em> + participe I) exprime une nécessité ou une possibilité, comme <em>sein + zu</em>. Pour lire un groupe long : sautez de l'article au nom, puis revenez en arrière et lisez à partir du participe vers la gauche.</p><p class='callout callout--trap'>Le français place ces compléments après le nom (<em>le livre acheté hier au magasin</em>). En allemand ils viennent avant, entre l'article et le nom, avec le participe à la fin du groupe : <em>das gestern im Laden gekaufte Buch</em>. C'est courant à l'écrit formel ; à l'oral on préfère la relative.</p>"
  }
});
